file.content:
            body_tenant = payload.get("tenant_id")
            if not isinstance(body_tenant, str) or not body_tenant:
                self._bad_request("field tenant_id must be a non-empty string")
                return
            tenant_id = self._tenant(parts, payload, audit=False)
            if tenant_id is None:
                return
            passphrase = payload.get("passphrase")
            if not isinstance(passphrase, str) or not passphrase:
                self._bad_request(
                    "field passphrase must be a non-empty string"
                )
                return
            bundle = payload.get("bundle")
            if not isinstance(bundle, str) or not bundle:
                self._bad_request("field bundle must be a non-empty string")
                return
            # An already-bound key replays/conflicts before we decrypt, so a
            # wrong passphrase on a retry neither masks a replay nor consumes
            # the key.
            if self._idempotent_precheck(
                parts.path, tenant_id, operator, payload, idem_key
            ):
                return
            # Decrypting/authenticating the bundle is side-effect free, so it
            # stays outside the idempotent binding: a wrong passphrase or a
            # tampered bundle is a plain 400 with no audit event and never
            # consumes the key.
            try:
                decoded = keybundle.decode_bundle(bundle, passphrase)
            except keybundle.BundleError as exc:
                self._bad_request(str(exc))
                return

            def execute(operation, mirror=None):
                key_id = decoded["key_id"]
                # Kind and exact key_id rule are durable before any business
                # check, so a 403/404/409 terminal replays from context alone.
                operation_store.update_details(
                    operation,
                    {"kind": "import", "key_id": key_id},
                )
                if mirror is not None:
                    mirror.describe(
                        {"kind": "import", "write_set": [key_id]}
                    )
                # Authorization precedes the conflict check: a denial is a
                # bound terminal 403 even when the key_id already exists for
                # another tenant.
                if not policy_store.is_allowed(
                    tenant_id, audit_mod.ACTION_IMPORT, operator
                ):
                    return self._idempotent_rejection(
                        operation, tenant_id, key_id,
                        audit_mod.ACTION_IMPORT, 403,
                        "action not permitted by policy",
                    )

                def stage_success(committed_record):
                    # After the new key file landed, before the commit-point
                    # append: stage the exact 201 body verbatim.
                    body = committed_record.to_create_response()
                    body["operation_id"] = operation.operation_id
                    operation_store.stage_terminal(operation, 201, body)

                # ProviderInvalidMaterial propagates to the guard (400). The
                # existence check and the create are atomic in the store.
                status, record = store.import_bundle(
                    tenant_id, decoded,
                    event_id=operation.operation_id,
                    lock_timeout=operations_mod.LOCK_WAIT_SECONDS,
                    pre_commit=stage_success,
                    mirror=mirror,
                )
                if status == IMPORT_CONFLICT:
                    if record.tenant_id == tenant_id:
                        return self._idempotent_rejection(
                            operation, tenant_id, record.key_id,
                            audit_mod.ACTION_IMPORT, 409,
                            "key_id already exists for this tenant",
                        )
                    # Same answer as a missing key: never confirm another
                    # tenant owns this key_id.
                    return self._idempotent_rejection(
                        operation, tenant_id, record.key_id,
                        audit_mod.ACTION_IMPORT, 404, "key not found",
                    )
                # The success event committed in the same transaction as file.
                return 201, record.to_create_response()

            self._idempotent_guard(
                parts.path, tenant_id, operator, payload, idem_key, execute
            )

        # -- tenant backup / restore --------------------------------------
        def _backup_tenant(self, parts, operator: str) -> None:
            """POST /v1/backup.

            The whole tenant (every key with all versions and private
            material, plus its policy) is returned only sealed inside the
            opaque tenant bundle. A tenant with no data backs up as an empty
            bundle (keys [], policy null).
            """
            payload = self._read_json_object()
            if payload is None:
                return
            body_tenant = payload.get("tenant_id")
            if not isinstance(body_tenant, str) or not body_tenant:
                if not self._record_conflict():
                    return
                self._bad_request("field tenant_id must be a non-empty string")
                return
            tenant_id = self._tenant(parts, payload)
            if tenant_id is None:
                return
            passphrase = payload.get("passphrase")
            if not isinstance(passphrase, str) or not passphrase:
                if not self._record_attempt(
                    tenant_id, None, audit_mod.ACTION_EXPORT,
                    audit_mod.OUTCOME_REJECTED,
                ):
                    return
                self._bad_request(
                    "field passphrase must be a non-empty string"
                )
                return
            if not self._enforce(
                tenant_id, None, audit_mod.ACTION_EXPORT, operator
            ):
                return
            try:
                bundle = coordinator.backup_bundle(tenant_id, passphrase)
            except LedgerError as exc:
                self._server_error(exc)
                return
            # A backup reads but never mutates; its event rides with the
            # successful response like a single-key export.
            if not self._record_attempt(
                tenant_id, None, audit_mod.ACTION_EXPORT,
                audit_mod.OUTCOME_SUCCESS,
            ):
                return
            self._send_json(
                200, {"format": tenantbundle.FORMAT, "bundle": bundle}
            )

        def _restore_tenant(self, parts, operator: str) -> None:
            """POST /v1/restore.

            The Idempotency-Key is checked before the body is read. Parse,
            parameter and decryption failures are side-effect-free 400s (no
            audit event, no operation record, no provider handle) and never
            consume the key. After the key is bound, authorization (import)
            precedes the in-bundle tenant check: a bundle naming another
            tenant answers 404. A key_id or policy already present for this
            tenant is a terminal 409 that changes nothing; an id occupied by
            another tenant answers 404. Every audit event for a restore
            carries key_id null and is named after the operation_id.
            """
            idem_key = self._idempotency_key()
            if idem_key is None:
                return
            payload = self._read_json_object(audit=False)
            if payload is None:
                return
            body_tenant = payload.get("tenant_id")
            if not isinstance(body_tenant, str) or not body_tenant:
                self._bad_request("field tenant_id must be a non-empty string")
                return
            tenant_id = self._tenant(parts, payload, audit=False)
            if tenant_id is None:
                return
            passphrase = payload.get("passphrase")
            if not isinstance(passphrase, str) or not passphrase:
                self._bad_request(
                    "field passphrase must be a non-empty string"
                )
                return
            bundle = payload.get("bundle")
            if not isinstance(bundle, str) or not bundle:
                self._bad_request("field bundle must be a non-empty string")
                return
            # An already-bound key replays/conflicts before we decrypt, so a
            # wrong passphrase on a retry never masks a replay.
            if self._idempotent_precheck(
                parts.path, tenant_id, operator, payload, idem_key
            ):
                return
            # Decrypting/authenticating the bundle is side-effect free, so it
            # stays outside the idempotent binding; a failure is a 400 with no
            # audit event and never consumes the key.
            try:
                decoded = tenantbundle.decode_bundle(bundle, passphrase)
            except tenantbundle.TenantBundleError as exc:
                self._bad_request(str(exc))
                return

            def execute(operation, mirror=None):
                key_ids = sorted(k["key_id"] for k in decoded["keys"])
                writes_policy = decoded["policy"] is not None
                # Kind and write-set facts are durable before any business
                # check. Restore events always project key_id null, enforced
                # by the rejection helper from kind == "restore".
                operation_store.update_details(
                    operation,
                    {
                        "kind": "restore",
                        "key_ids": key_ids,
                        "policy_restored": writes_policy,
                    },
                )
                if mirror is not None:
                    mirror.describe(
                        {
                            "kind": "restore",
                            "write_set": key_ids,
                            "policy": writes_policy,
                        }
                    )
                # Authorization (import) precedes the in-bundle tenant check.
                if not policy_store.is_allowed(
                    tenant_id, audit_mod.ACTION_IMPORT, operator
                ):
                    return self._idempotent_rejection(
                        operation, tenant_id, None,
                        audit_mod.ACTION_IMPORT, 403,
                        "action not permitted by policy",
                    )
                if decoded["tenant_id"] != tenant_id:
                    # The sealed bundle belongs to another tenant: answer like
                    # a missing object so existence never leaks.
                    return self._idempotent_rejection(
                        operation, tenant_id, None,
                        audit_mod.ACTION_IMPORT, 404,
                        "tenant backup not found",
                    )

                def stage_success():
                    # After the write set landed, before the single
                    # commit-point append: stage the exact 201 body verbatim.
                    body = {
                        "tenant_id": tenant_id,
                        "key_ids": key_ids,
                        "policy_restored": writes_policy,
                        "operation_id": operation.operation_id,
                    }
                    operation_store.stage_terminal(operation, 201, body)

                # ProviderInvalidMaterial (400) and LedgerError (500)
                # propagate to the guard; the coordinator has already removed
                # every written file on a ledger failure.
                result = coordinator.restore(
                    tenant_id, decoded,
                    event_id=operation.operation_id,
                    lock_timeout=operations_mod.LOCK_WAIT_SECONDS,
                    pre_commit=stage_success,
                    mirror=mirror,
                )
                if result.status == restore_mod.RESTORE_CREATED:
                    # The single success event committed with the files.
                    return (
                        201,
                        {
                            "tenant_id": result.tenant_id,
                            "key_ids": result.key_ids,
                            "policy_restored": result.policy_restored,
                        },
                    )
                if result.status == restore_mod.RESTORE_SAME_TENANT_CONFLICT:
                    return self._idempotent_rejection(
                        operation, tenant_id, None,
                        audit_mod.ACTION_IMPORT, 409,
                        "backup target already contains this data",
                    )
                return self._idempotent_rejection(
                    operation, tenant_id, None,
                    audit_mod.ACTION_IMPORT, 404,
                    "tenant backup not found",
                )

            self._idempotent_guard(
                parts.path, tenant_id, operator, payload, idem_key, execute
            )

        # -- provider health / reconnect ----------------------------------
        def _no_tenant(self, parts) -> bool:
            """Reject a tenant_id on a provider-scoped endpoint with a 400.

            The provider endpoints are global, not tenant scoped: they carry
            the single operator header only and accept no tenant_id in a
            header, query string or body. A supplied tenant_id is a parameter
            error. These endpoints never write audit events.
            """
            if self.headers.get_all("X-Tenant-Id"):
                self._bad_request(
                    "field tenant_id is not accepted by this endpoint"
                )
                return False
            if parse_qs(parts.query, keep_blank_values=True).get("tenant_id"):
                self._bad_request(
                    "field tenant_id is not accepted by this endpoint"
                )
                return False
            return True

        def _no_tenant_body(self) -> bool:
            """Reject a non-empty request body carrying tenant_id with a 400.

            Read before any factory build or health probe: a body that
            mentions tenant_id is a parameter error naming the field.
            """
            try:
                length = int(self.headers.get("Content-Length", 0))
            except ValueError:
                self._bad_request("invalid Content-Length")
                return False
            raw = self.rfile.read(length) if length > 0 else b""
            if raw and "tenant_id" in raw.decode("utf-8", "replace"):
                self._bad_request(
                    "field tenant_id is not accepted by this endpoint"
                )
                return False
            return True

        def _provider_status(self) -> None:
            """GET /v1/provider/status.

            200 with keys in order ``provider_id,status``; status is only
            ``ready`` or ``unavailable``. A provider that cannot be loaded
            reports ``provider_id`` null (the probe builds it lazily). The
            readiness text/exception never leaves the process. A tenant_id
            in a header, the query or a non-empty body is a 400 before any
            factory build or health probe.
            """
            parts = urlsplit(self.path)
            if not self._no_tenant(parts):
                return
            if not self._no_tenant_body():
                return
            body = provider_mod.provider_status()
            self._send_json(
                200,
                {
                    "provider_id": body["provider_id"],
                    "status": body["status"],
                },
            )

        def _provider_reconnect(self) -> None:
            """POST /v1/provider/reconnect.

            The body must be exactly ``{}``: bad JSON or any extra field is a
            side-effect-free 400. On success the factory is rebuilt from the
            current configuration, contract-validated and health-checked
            behind the shared five-second gate; 200 returns the same
            ``provider_id,status`` body. Any failure keeps the old instance
            and answers a fixed 503 whose body never carries backend detail.
            """
            parts = urlsplit(self.path)
            if not self._no_tenant(parts):
                return
            try:
                length = int(self.headers.get("Content-Length", 0))
            except ValueError:
                self._bad_request("invalid Content-Length")
                return
            raw = self.rfile.read(length) if length > 0 else b""
            try:
                payload = json.loads(raw.decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                self._bad_request("request body must be valid JSON")
                return
            # Exactly the empty object: a non-object or any extra field is a
            # 400 that happens before the factory is touched (zero side
            # effects, no audit event). A tenant_id field is named directly.
            if isinstance(payload, dict) and "tenant_id" in payload:
                self._bad_request(
                    "field tenant_id is not accepted by this endpoint"
                )
                return
            if not isinstance(payload, dict) or payload:
                self._bad_request("request body must be exactly {}")
                return
            try:
                body = provider_mod.reconnect()
            except ProviderUnavailable:
                self._send_json(
                    503,
                    {"error": "key management provider is unavailable"},
                )
                return
            self._send_json(
                200,
                {
                    "provider_id": body["provider_id"],
                    "status": body["status"],
                },
            )

        def _provider_switchover(self) -> None:
            """POST /v1/provider/switchover.

            Directed switch of the active KMS/HSM provider to one NAMED
            chain entry. Like reconnect it needs only the single non-empty
            X-Operator-Id and rejects any tenant_id (header, query or body)
            with a side-effect-free 400. The body must be strictly
            ``{"provider_id": P}`` with P a non-empty string: bad JSON, a
            non-object, a missing/empty/non-string provider_id or any extra
            field is a 400 naming the field before the gate or factory is
            touched. A provider switchover only works with
            ``KEYMGR_PROVIDER_CHAIN`` configured: no chain, or a P that is
            not a chain entry, is likewise a 400. Success drains in-flight
            calls behind the shared five-second gate, commits
            ``switching`` (old id, P, the original generation, reason
            reconnect) then ``ready`` (P, null, generation+1) and answers
            200 ``provider_id,status`` (P, ``ready``); P already active is
            a healthy 200 with the generation unchanged. A target that
            fails to build/contract-validate/configure/probe healthy, or a
            budget exhausted while waiting, answers the fixed 503 with zero
            side effects.
            """
            parts = urlsplit(self.path)
            if not self._no_tenant(parts):
                return
            try:
                length = int(self.headers.get("Content-Length", 0))
            except ValueError:
                self._bad_request("invalid Content-Length")
                return
            raw = self.rfile.read(length) if length > 0 else b""
            try:
                payload = json.loads(raw.decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                self._bad_request("request body must be valid JSON")
                return
            # A tenant_id field is named directly, like on reconnect.
            if isinstance(payload, dict) and "tenant_id" in payload:
                self._bad_request(
                    "field tenant_id is not accepted by this endpoint"
                )
                return
            if not isinstance(payload, dict):
                self._bad_request("request body must be a JSON object")
                return
            # Strictly {"provider_id": P}: every other field is a 400 naming
            # it, before the provider is touched (zero side effects).
            extra = [key for key in payload if key != "provider_id"]
            if extra:
                self._bad_request(
                    "field %s is not accepted by this endpoint" % extra[0]
                )
                return
            target = payload.get("provider_id")
            if not isinstance(target, str) or not target:
                self._bad_request(
                    "field provider_id must be a non-empty string"
                    if "provider_id" in payload
                    else "missing required field: provider_id"
                )
                return
            try:
                body = provider_mod.switchover(target)
            except ProviderSwitchoverInvalid as exc:
                # No chain configured, or P is not a chain entry: 400 naming
                # provider_id, with no state write, swap or audit event.
                self._bad_request(str(exc))
                return
            except ProviderUnavailable:
                self._send_json(
                    503,
                    {"error": "key management provider is unavailable"},
                )
                return
            self._send_json(
                200,
                {
                    "provider_id": body["provider_id"],
                    "status": body["status"],
                },
            )

        # -- GET ----------------------------------------------------------
        def do_GET(self) -> None:
            parts = urlsplit(self.path)
            path = parts.path

            operator = self._operator()
            if operator is None:
                return

            operation_match = _OPERATIONS_PATH_RE.match(path)
            if operation_match is not None:
                self._get_operation(
                    operation_match.group(1), parts, operator
                )
                return

            if path == _AUDIT_PATH:
                # Audit failures are 500, not audited themselves.
                try:
                    self._get_audit(parts, operator)
                except LedgerError as exc:
                    self._server_error(exc)
                return

            if path == _KEYS_PATH:
                try:
                    self._list_keys(parts, operator)
                except LedgerError as exc:
                    self._server_error(exc)
                return

            if path == _POLICY_PATH:
                try:
                    self._get_policy(parts)
                except LedgerError as exc:
                    self._server_error(exc)
                return

            if path == _PROVIDER_STATUS_PATH:
                self._provider_status()
                return

            try:
                version_match = _VERSION_PATH_RE.match(path)
                if version_match is not None:
                    self._get_version(
                        version_match.group(1), version_match.group(2),
                        parts, operator,
                    )
                    return

                current_match = _CURRENT_PATH_RE.match(path)
                if current_match is not None:
                    self._get_current(
                        current_match.group(1), parts, operator
                    )
                    return

                status_match = _STATUS_PATH_RE.match(path)
                if status_match is not None:
                    self._get_status(
                        status_match.group(1), parts, operator
                    )
                    return

                key_match = _KEY_PATH_RE.match(path)
                if key_match is not None:
                    self._get_key(key_match.group(1), parts, operator)
                    return
            except LedgerError as exc:
                self._server_error(exc)
                return

            self._send_json(404, {"error": "not found" })

        def _reject_read(self, tenant_id, key_id, status, message) -> None:
            if not self._record_attempt(
                tenant_id, key_id, audit_mod.ACTION_READ,
                audit_mod.OUTCOME_REJECTED,
            ):
                return
            self._send_json(status, {"error": message})

        def _get_key(self, key_id: str, parts, operator: str) -> None:
            tenant_id = self._tenant(parts)
            if tenant_id is None:
                return
            if self._bad_key_id(key_id):
                return
            if not self._enforce(
                tenant_id, key_id, audit_mod.ACTION_READ, operator
            ):
                return
            record = store.get(key_id, tenant_id)
            if record is None:
                # Same status whether the key is missing or owned by another
                # tenant: never confirm the existence of another tenant's key.
                self._reject_read(tenant_id, key_id, 404, "key not found")
                return
            if not self._record_attempt(
                tenant_id, key_id, audit_mod.ACTION_READ,
                audit_mod.OUTCOME_SUCCESS,
            ):
                return
            self._send_json(200, record.to_get_response())

        def _get_version(self, key_id: str, raw_version: str, parts,
                         operator: str) -> None:
            tenant_id = self._tenant(parts)
            if tenant_id is None:
                return
            if self._bad_key_id(key_id):
                return
            version = self._parse_version(raw_version)
            if version is None:
                # Bad version parameter: tenant and key are known, so the
                # rejection is visible to them.
                self._reject_read(
                    tenant_id, key_id, 400,
                    "field version must be a positive integer",
                )
                return
            if not self._enforce(
                tenant_id, key_id, audit_mod.ACTION_READ, operator
            ):
                return
            result = store.get_version(key_id, tenant_id, version)
            if result is None:
                # Unknown key, unknown version and cross-tenant access are
                # indistinguishable, all 404.
                self._reject_read(
                    tenant_id, key_id, 404, "version not found"
                )
                return
            if not self._record_attempt(
                tenant_id, key_id, audit_mod.ACTION_READ,
                audit_mod.OUTCOME_SUCCESS,
            ):
                return
            _record, ver = result
            self._send_json(200, ver.to_version_response(key_id))

        def _get_current(self, key_id: str, parts, operator: str) -> None:
            tenant_id = self._tenant(parts)
            if tenant_id is None:
                return
            if self._bad_key_id(key_id):
                return
            if not self._enforce(
                tenant_id, key_id, audit_mod.ACTION_READ, operator
            ):
                return
            record = store.get(key_id, tenant_id)
            if record is None:
                self._reject_read(tenant_id, key_id, 404, "key not found")
                return
            if not self._record_attempt(
                tenant_id, key_id, audit_mod.ACTION_READ,
                audit_mod.OUTCOME_SUCCESS,
            ):
                return
            self._send_json(200, record.current.to_version_response(key_id))

        def _get_status(self, key_id: str, parts, operator: str) -> None:
            tenant_id = self._tenant(parts)
            if tenant_id is None:
                return
            if self._bad_key_id(key_id):
                return
            if not self._enforce(
                tenant_id, key_id, audit_mod.ACTION_READ, operator
            ):
                return
            record = store.get(key_id, tenant_id)
            if record is None:
                self._reject_read(tenant_id, key_id, 404, "key not found")
                return
            if not self._record_attempt(
                tenant_id, key_id, audit_mod.ACTION_READ,
                audit_mod.OUTCOME_SUCCESS,
            ):
                return
            self._send_json(200, record.to_status_response())

        # -- operations ----------------------------------------------------
        def _get_operation(self, operation_id: str, parts, operator: str) -> None:
            """GET /v1/operations/{operation_id}.

            Scoped to exactly one tenant (single header or single query
            parameter) and the single operator. An unknown id, a malformed id,
            an operation owned by another tenant or by another operator all
            answer 404 so existence never leaks.
            """
            tenant_id = self._audit_tenant(parts)
            if tenant_id is None:
                return
            record = operation_store.get(operation_id, tenant_id, operator)
            if record is None:
                self._send_json(404, {"error": "operation not found"})
                return
            self._send_json(200, record.to_status_response())

        # -- key listing ---------------------------------------------------
        def _list_keys(self, parts, operator: str) -> None:
            """GET /v1/keys: one paginated snapshot of the tenant's keys.

            The tenant comes from exactly one non-empty source (single
            X-Tenant-Id header or single ?tenant_id= parameter), like the
            audit endpoint. Every query parameter is single-valued:
            ``status`` (active|revoked), ``algorithm`` (AES256|RSA2048),
            ``limit`` (1-1000, default 100) and ``cursor``; a duplicate,
            empty, illegal or out-of-range value is a 400 naming the field,
            and all parameter validation precedes authorization. A policy
            denial is a 403 with one rejected ``list`` event (key_id null);
            a success appends one ``list`` success event (key_id null) and
            answers 200 with keys in the order ``items,next_cursor``.
            """
            tenant_id = self._audit_tenant(parts)
            if tenant_id is None:
                return
            qs = parse_qs(parts.query, keep_blank_values=True)

            values, errored = self._single_param(qs, "status")
            if errored:
                return
            status = values[0] if values else None
            if status is not None and status not in ("active", "revoked"):
                self._bad_request(
                    "field status must be one of: active, revoked"
                )
                return

            values, errored = self._single_param(qs, "algorithm")
            if errored:
                return
            algorithm = values[0] if values else None
            if algorithm is not None and algorithm not in SUPPORTED_ALGORITHMS:
                self._bad_request(
                    "unsupported value for field algorithm: %r (supported: %s)"
                    % (algorithm, ", ".join(SUPPORTED_ALGORITHMS))
                )
                return

            limit = 100
            values, errored = self._single_param(qs, "limit")
            if errored:
                return
            if values:
                raw_limit = values[0]
                if not _POSITIVE_INT_RE.fullmatch(raw_limit):
                    self._bad_request(
                        "field limit must be an integer between 1 and 1000"
                    )
                    return
                limit = int(raw_limit)
                if not 1 <= limit <= 1000:
                    self._bad_request(
                        "field limit must be an integer between 1 and 1000"
                    )
                    return

            values, errored = self._single_param(qs, "cursor")
            if errored:
                return
            cursor = values[0] if values else None

            # Parameter validation (400) precedes authorization; a policy
            # rejection of a key list is recorded with the original action
            # ("list") and outcome rejected, key_id null.
            if not self._enforce(
                tenant_id, None, audit_mod.ACTION_LIST, operator
            ):
                return

            try:
                page = store.list_page(
                    tenant_id,
                    status=status,
                    algorithm=algorithm,
                    limit=limit,
                    cursor=cursor,
                )
            except InvalidCursor:
                self._bad_request("invalid or expired cursor")
                return
            if not self._record_attempt(
                tenant_id, None, audit_mod.ACTION_LIST,
                audit_mod.OUTCOME_SUCCESS,
            ):
                return
            self._send_json(
                200,
                {
                    "items": [r.to_list_response() for r in page.records],
                    "next_cursor": page.next_cursor,
                },
            )

        # -- audit ---------------------------------------------------------
        def _single_param(self, qs, name):
            """Return (values, error_sent). Exactly one value or 400."""
            values = qs.get(name, [])
            if len(values) > 1:
                self._bad_request("duplicate %s parameter" % name)
                return None, True
            return values, False

        def _get_audit(self, parts, operator: str) -> None:
            tenant_id = self._audit_tenant(parts)
            if tenant_id is None:
                return
            qs = parse_qs(parts.query, keep_blank_values=True)

            values, errored = self._single_param(qs, "key_id")
            if errored:
                return
            key_id = values[0] if values else None
            if key_id is not None and not is_valid_key_id(key_id):
                # An illegal identifier is a tenant_conflict event, like any
                # other malformed tenant/key parameter.
                if self._record_conflict():
                    self._bad_request("field key_id must be a UUID4")
                return

            values, errored = self._single_param(qs, "action")
            if errored:
                return
            action = values[0] if values else None
            if action is not None and action not in audit_mod.ACTIONS:
                self._bad_request(
                    "field action must be one of: %s"
                    % ", ".join(audit_mod.ACTIONS)
                )
                return

            limit = 100
            values, errored = self._single_param(qs, "limit")
            if errored:
                return
            if values:
                raw_limit = values[0]
                if not _POSITIVE_INT_RE.fullmatch(raw_limit):
                    self._bad_request(
                        "field limit must be an integer between 1 and 1000"
                    )
                    return
                limit = int(raw_limit)
                if not 1 <= limit <= 1000:
                    self._bad_request(
                        "field limit must be an integer between 1 and 1000"
                    )
                    return

            values, errored = self._single_param(qs, "cursor")
            if errored:
                return
            cursor = values[0] if values else None

            # Parameter validation (400) precedes authorization; a policy
            # rejection of an audit query is recorded with the original
            # action ("audit") and outcome rejected, key_id null.
            if not self._enforce(
                tenant_id, None, audit_mod.ACTION_AUDIT, operator
            ):
                return

            try:
                page = store.audit.query(
                    tenant_id,
                    key_id=key_id,
                    action=action,
                    limit=limit,
                    cursor=cursor,
                )
            except InvalidCursor:
                self._bad_request("invalid or expired cursor")
                return
            self._send_json(
                200,
                {
                    "events": [e.to_response() for e in page.events],
                    "next_cursor": page.next_cursor,
                },
            )

        # -- policy management --------------------------------------------
        def _strict_tenant(self, parts):
            """Single header or single query tenant, with conflict auditing.

            Same rules as _audit_tenant (simultaneous/duplicate/empty/missing
            is a 400 naming tenant_id), but the failure is also written to the
            ledger as an invisible tenant_conflict event. Used by the policy
            management endpoints.
            """
            headers = self.headers.get_all("X-Tenant-Id") or []
            query_values = parse_qs(
                parts.query, keep_blank_values=True
            ).get("tenant_id", [])

            def fail(message: str) -> None:
                if self._record_conflict():
                    self._bad_request(message)

            if len(headers) > 1:
                fail("duplicate tenant_id (provide a single X-Tenant-Id header)")
                return None
            if len(query_values) > 1:
                fail("duplicate tenant_id (provide a single tenant_id parameter)")
                return None
            if headers and query_values:
                fail(
                    "conflicting tenant_id parameters (use header or query, not both)"
                )
                return None
            tenant = headers[0] if headers else (
                query_values[0] if query_values else None
            )
            if tenant is None:
                fail("missing required field: tenant_id")
                return None
            if not tenant:
                fail("field tenant_id must be a non-empty string")
                return None
            return tenant

        def do_PUT(self) -> None:
            parts = urlsplit(self.path)
            if parts.path != _POLICY_PATH:
                self._send_json(404, {"error": "not found"})
                return
            operator = self._operator()
            if operator is None:
                return
            try:
                self._put_policy(parts)
            except LedgerError as exc:
                self._server_error(exc)

        def do_DELETE(self) -> None:
            parts = urlsplit(self.path)
            if parts.path != _POLICY_PATH:
                self._send_json(404, {"error": "not found"})
                return
            operator = self._operator()
            if operator is None:
                return
            try:
                self._delete_policy(parts)
            except LedgerError as exc:
                self._server_error(exc)

        def _get_policy(self, parts) -> None:
            tenant_id = self._strict_tenant(parts)
            if tenant_id is None:
                return
            rules = policy_store.get(tenant_id)
            if rules is None:
                self._send_json(404, {"error": "policy not found"})
                return
            policy_store.audit_read(tenant_id)
            self._send_json(
                200,
                {
                    "tenant_id": tenant_id,
                    "rules": [r.to_json() for r in rules],
                },
            )

        def _put_policy(self, parts) -> None:
            payload = self._read_json_object()
            if payload is None:
                return
            body_tenant = payload.get("tenant_id")
            if not isinstance(body_tenant, str) or not body_tenant:
                if self._record_conflict():
                    self._bad_request(
                        "field tenant_id must be a non-empty string"
                    )
                return
            tenant_id = self._tenant(parts, payload)
            if tenant_id is None:
                return
            if "rules" not in payload:
                self._bad_request("missing required field: rules")
                return
            try:
                rules = validate_rules(payload["rules"])
            except PolicyError as exc:
                self._bad_request(str(exc))
                return
            policy_store.put(tenant_id, rules)
            self._send_json(
                200,
                {
                    "tenant_id": tenant_id,
                    "rules": [r.to_json() for r in rules],
                },
            )

        def _delete_policy(self, parts) -> None:
            tenant_id = self._strict_tenant(parts)
            if tenant_id is None:
                return
            policy_store.delete(tenant_id)
            self._send_json(200, {"tenant_id": tenant_id, "deleted": True})

    return KeyHandler


def _resolve_committed_operation(store, policy_store, record, event):
    """Rebuild the terminal response of a committed-but-unfinished operation.

    Runs during startup recovery after the key/restore outbox recovery has
    made the mutation durable. The audit event named after the operation_id
    is the durable fact: a ``success`` event rebuilds the original 201
    response, while a ``rejected`` event rebuilds the exact 403/404/409
    terminal (its state, error body and audit projection) from the recorded
    action/key_id and the current tenant state. Returns
    ``(http_status, response)``.
    """
    op_id = record.operation_id
    details = record.details or {}
    kind = details.get("kind")
    tenant_id = record.tenant_id
    operator_id = record.operator_id

    def error(status: int, message: str):
        return status, {"error": message, "operation_id": op_id}

    if event.outcome == audit_mod.OUTCOME_REJECTED:
        action = event.action
        terminal = details.get("terminal")
        # A batch rotation is AUTHORIZED as rotate even though its audit
        # action is batch_rotate; map back for the legacy no-terminal policy
        # reconstruction below.
        policy_action = (
            audit_mod.ACTION_ROTATE
            if action == audit_mod.ACTION_BATCH_ROTATE
            else action
        )

        def message_for(status: int) -> str:
            if status == 403:
                return "action not permitted by policy"
            if status == 409:
                if kind == "restore":
                    return "backup target already contains this data"
                if kind == "migrate":
                    return "key is already managed by the ready provider"
                return "key_id already exists for this tenant"
            if kind == "restore":
                return "tenant backup not found"
            return "key not found"

        # The original terminal status is persisted with the event: replay it
        # verbatim, so a policy change or a state change after the crash can
        # never turn a 403 into a 404/409 or vice versa.
        if terminal in (403, 404, 409):
            return error(terminal, message_for(terminal))

        # Older records without the stashed terminal: infer once from the
        # durable action and the current state.
        # A policy denial outranks existence: it is reconstructed whenever the
        # tenant's policy currently rejects this operator/action.
        if not policy_store.is_allowed(tenant_id, policy_action, operator_id):
            return error(403, message_for(403))
        if kind == "restore":
            # A same-tenant conflict is reconstructed when any key from the
            # write set now belongs to the tenant, a restored policy exists,
            # or (empty bundle) the persistent empty-restore marker is on
            # disk. Every other rejection (in-bundle tenant mismatch, foreign
            # occupation) replays as 404. Restore events always carry
            # key_id null.
            for key_id in details.get("key_ids", []):
                raw = store.read_raw(key_id)
                if raw is not None and raw.tenant_id == tenant_id:
                    return error(409, message_for(409))
            if details.get("policy_restored") and policy_store.get(
                tenant_id
            ) is not None:
                return error(409, message_for(409))
            digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
            marker = os.path.join(
                store.data_dir, "restore-empty-" + digest + ".json"
            )
            if os.path.exists(marker):
                return error(409, message_for(409))
            return error(404, message_for(404))
        if kind == "import":
            key_id = event.key_id or details.get("key_id")
            raw = store.read_raw(key_id) if is_valid_key_id(key_id) else None
            if raw is not None and raw.tenant_id == tenant_id:
                return error(409, message_for(409))
            return error(404, message_for(404))
        # rotate (and any unknown shape): a rejected rotate means the key was
        # unknown or foreign at commit time and no version was appended.
        return error(404, message_for(404))

    if kind == "migrate":
        key_id = event.key_id or details.get("key_id")
        key = store.get(key_id, tenant_id)
        if key is not None:
            return (
                200,
                {
                    "key_id": key_id,
                    "provider_id": key.current.provider_id,
                    "versions": sorted(ver.version for ver in key.versions),
                    "operation_id": op_id,
                },
            )
        return 200, {"operation_id": op_id}
    if kind == "rotate":
        key_id = event.key_id or details.get("key_id")
        key = store.get(key_id, tenant_id)
        if key is not None:
            # The committed version is the one whose creation time equals the
            # event timestamp; fall back to the current pointer.
            ver = None
            for candidate in key.versions:
                if candidate.created_at == event.timestamp:
                    ver = candidate
                    break
            if ver is None:
                ver = key.current
            return (
                201,
                {
                    "key_id": key_id,
                    "version": ver.version,
                    "algorithm": ver.algorithm,
                    "public_key": ver.public_key,
                    "operation_id": op_id,
                },
            )
    if kind == "batch_rotate":
        # The batch's single event carries key_id null; the request-order
        # item set is durable in details. Rebuild each item's committed
        # version (the one minted at the event timestamp, else the current
        # pointer). A key that is no longer readable makes the projection fall
        # back to operation_id-only rather than fabricating a version.
        result_items = []
        complete = True
        for one in details.get("items", []):
            key_id = one.get("key_id")
            key = (
                store.get(key_id, tenant_id)
                if is_valid_key_id(key_id)
                else None
            )
            if key is None:
                complete = False
                break
            ver = None
            for candidate in key.versions:
                if candidate.created_at == event.timestamp:
                    ver = candidate
                    break
            if ver is None:
                ver = key.current
            result_items.append(
                {
                    "key_id": key_id,
                    "version": ver.version,
                    "algorithm": ver.algorithm,
                    "public_key": ver.public_key,
                }
            )
        if complete:
            return 201, {"items": result_items, "operation_id": op_id}
    if kind == "import":
        key_id = event.key_id or details.get("key_id")
        key = store.get(key_id, tenant_id)
        if key is not None:
            body = key.to_create_response()
            body["operation_id"] = op_id
            return 201, body
    if kind == "restore":
        return (
            201,
            {
                "tenant_id": tenant_id,
                "key_ids": details.get("key_ids", []),
                "policy_restored": details.get("policy_restored", False),
                "operation_id": op_id,
            },
        )
    # Cannot rebuild the projection; the mutation did commit, so keep it
    # succeeded with an operation_id-only body rather than pending forever.
    return 201, {"operation_id": op_id}


def serve(host: str, port: int, data_dir: str) -> None:
    """Run the HTTP server until interrupted."""
    audit_log = AuditLog(data_dir)
    # Key-store and restore outbox recovery run first (constructors), so a
    # half-committed mutation's files/handles are settled before the
    # operation store resolves the pending operation that wrapped it.
    store = KeyStore(data_dir, audit_log)
    policy_store = PolicyStore(data_dir, audit_log)
    coordinator = restore_mod.RestoreCoordinator(store, policy_store)
    operation_store = OperationStore(data_dir, audit_log)
    # The artifact mirrors settle next (after the outbox recovery): a
    # consistent mirror is cleaned, a fully rolled-back attempt's mirror is
    # dropped, and an unprovable scene keeps both its evidence and its
    # operation pending for a later open.
    from .artifacts import ArtifactStore

    artifact_store = ArtifactStore(data_dir, store, audit_log)
    artifact_store.settle_pending(operation_store)
    operation_store.recover_pending(
        lambda record, event: _resolve_committed_operation(
            store, policy_store, record, event
        ),
        is_parked=artifact_store.is_parked,
    )
    httpd = ThreadingHTTPServer(
        (host, port),
        make_handler(
            store, policy_store, coordinator, operation_store, artifact_store
        ),
    )
    httpd.daemon_threads = True
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()

"""Per-tenant action policies: validation, persistence and enforcement.

A policy document is a list of rules; each rule binds a ``subject`` (the
X-Operator-Id of the caller), a set of ``actions`` and an ``effect`` of
``allow`` or ``deny``. Enforcement, for one (tenant, subject, action):

* a tenant with no document is unrestricted (every action is allowed);
* among the rules whose subject equals the caller and whose actions contain
  the action, any ``deny`` wins over ``allow``;
* if no matching rule exists the action is denied (default deny).

Documents are stored as one JSON file per tenant, written through the same
outbox transaction as key records: the file first lands carrying the audit
event, the ledger append follows, then the marker is cleared; a crash in
between is repaired idempotently on the next open.
"""

import hashlib
import json
import os
import tempfile
import threading
from contextlib import contextmanager
from dataclasses import dataclass
from typing import Iterator, List, Optional

from . import audit as audit_mod
from .audit import AuditEvent, AuditLog, LedgerError

try:  # fcntl is POSIX-only; policy writes still work without it.
    import fcntl
except ImportError:  # pragma: no cover - non-POSIX platforms
    fcntl = None

# Actions a policy rule can govern. These are the same action names the audit
# ledger uses (the management actions policy_* are deliberately not governable).
POLICY_ACTIONS = (
    "create",
    "read",
    "rotate",
    "revoke",
    "import",
    "export",
    "migrate",
    "encrypt",
    "decrypt",
    "audit",
    "list",
)
EFFECTS = ("allow", "deny")
_POLICY_DIR = "policies"


class PolicyError(ValueError):
    """A policy document or rule failed validation (surfaced as 400)."""


@dataclass(frozen=True)
class Rule:
    """One policy rule: an effect on a set of actions for one subject."""

    subject: str
    actions: List[str]
    effect: str

    def to_json(self) -> dict:
        """Serialize to a plain dict; actions are emitted sorted."""
        return {
            "subject": self.subject,
            "actions": list(self.actions),
            "effect": self.effect,
        }

    @classmethod
    def from_json(cls, data: dict) -> "Rule":
        # Documents on disk were validated when written, but validate again
        # on the way in so a hand-edited file can never break enforcement.
        return validate_rule(data)

    def signature(self):
        """Dedup key: same subject/effect with the same unordered action set."""
        return self.subject, self.effect, frozenset(self.actions)


def validate_rule(raw, index: Optional[int] = None) -> Rule:
    """Validate one rule object; raise PolicyError naming the bad field.

    ``index`` prefixes field names with ``rules[i].`` when the rule comes from
    a document; a standalone rule names the bare fields.
    """
    where = "rules[%d]." % index if index is not None else ""

    def err(message: str) -> PolicyError:
        return PolicyError(message)

    if not isinstance(raw, dict):
        raise err("field %s must be an object" % (where.rstrip(".") if index is not None else "rule"))
    known = {"subject", "actions", "effect"}
    unknown = set(raw) - known
    if unknown:
        raise err(
            "unknown field %s%s"
            % (where, sorted(unknown)[0])
        )
    subject = raw.get("subject")
    if not isinstance(subject, str) or not subject:
        raise err("field %ssubject must be a non-empty string" % where)
    effect = raw.get("effect")
    if not isinstance(effect, str) or effect not in EFFECTS:
        raise err(
            "field %seffect must be one of: %s"
            % (where, ", ".join(EFFECTS))
        )
    actions = raw.get("actions")
    if not isinstance(actions, list) or not actions:
        raise err(
            "field %sactions must be a non-empty array" % where
        )
    clean_actions = []
    for action in actions:
        if not isinstance(action, str) or not action:
            raise err(
                "field %sactions must be non-empty strings" % where
            )
        if action not in POLICY_ACTIONS:
            raise err(
                "field %sactions has unknown action %r (allowed: %s)"
                % (where, action, ", ".join(POLICY_ACTIONS))
            )
        if action not in clean_actions:
            # Duplicates within one rule are dropped, not an error: the action
            # set is unordered, so ["read", "read"] carries no extra meaning.
            clean_actions.append(action)
    return Rule(subject=subject, actions=clean_actions, effect=effect)


def validate_rules(raw) -> List[Rule]:
    """Validate a full rules array; [] is valid and means default-deny."""
    if not isinstance(raw, list):
        raise PolicyError("field rules must be an array")
    rules: List[Rule] = []
    seen = set()
    for index, item in enumerate(raw):
        rule = validate_rule(item, index)
        if rule.signature() in seen:
            raise PolicyError(
                "field rules contains a duplicate rule at index %d "
                "(same subject, effect and unordered actions)" % index
            )
        seen.add(rule.signature())
        rules.append(rule)
    return rules


class PolicyStore:
    """File-backed per-tenant policy documents."""

    def __init__(self, data_dir: str, audit_log: Optional[AuditLog] = None) -> None:
        self.data_dir = data_dir
        self.dir_path = os.path.join(data_dir, _POLICY_DIR)
        os.makedirs(self.dir_path, exist_ok=True)
        self.audit = audit_log if audit_log is not None else AuditLog(data_dir)
        self._write_lock = threading.Lock()
        self._recover_pending_events()

    # -- on-disk shape -----------------------------------------------------
    def path_for(self, tenant_id: str) -> str:
        """Public accessor for a tenant's policy document path."""
        return self._path_for(tenant_id)

    def _path_for(self, tenant_id: str) -> str:
        # Tenant ids are free-form strings, so never use them as a filename:
        # key the file by a digest of the tenant instead.
        digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
        return os.path.join(self.dir_path, digest + ".json")

    def _lock_path_for(self, tenant_id: str) -> str:
        digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
        return os.path.join(self.dir_path, digest + ".lock")

    @contextmanager
    def tenant_lock(
        self, tenant_id: str, timeout: Optional[float] = None
    ) -> Iterator[None]:
        """Serialize all writes to one tenant's policy across processes.

        Pairs the in-process write lock with an exclusive ``fcntl`` lock on a
        per-tenant sidecar file, so a put/delete/restore/backup in another
        process cannot interleave with this one's read-modify-write. With a
        finite ``timeout`` (idempotent restore) the wait is bounded and raises
        :class:`~keymgr.store.LockTimeout` when it elapses.
        """
        import time as _time

        from .store import LockTimeout

        deadline = None if timeout is None else _time.monotonic() + timeout
        if timeout is None:
            self._write_lock.acquire()
        else:
            if not self._write_lock.acquire(timeout=max(timeout, 0.0)):
                raise LockTimeout("policy:" + tenant_id)
        if fcntl is None:  # pragma: no cover - non-POSIX platforms
            try:
                yield
            finally:
                self._write_lock.release()
            return
        fd = os.open(
            self._lock_path_for(tenant_id), os.O_RDWR | os.O_CREAT, 0o600
        )
        acquired = False
        try:
            if deadline is None:
                fcntl.flock(fd, fcntl.LOCK_EX)
            else:
                while True:
                    try:
                        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                        break
                    except BlockingIOError:
                        remaining = deadline - _time.monotonic()
                        if remaining <= 0:
                            raise LockTimeout("policy:" + tenant_id)
                        _time.sleep(min(0.02, remaining))
            acquired = True
            yield
        finally:
            if acquired:
                fcntl.flock(fd, fcntl.LOCK_UN)
            os.close(fd)
            self._write_lock.release()

    def _write_atomic(self, path: str, payload: dict) -> None:
        fd, tmp_path = tempfile.mkstemp(dir=self.dir_path, suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(payload, fh)
                fh.flush()
                os.fsync(fh.fileno())
            os.chmod(tmp_path, 0o600)
            os.replace(tmp_path, path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    def _read_doc(self, path: str):
        """Return (tenant_id, rules, pending_event), or None if unreadable."""
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except (OSError, ValueError):
            return None
        try:
            rules = [Rule.from_json(r) for r in data["rules"]]
            return data["tenant_id"], rules, data.get("pending_event")
        except (KeyError, TypeError, ValueError, PolicyError):
            return None

    def _recover_pending_events(self) -> None:
        """Commit outbox events left pending by a crashed process."""
        try:
            names = os.listdir(self.dir_path)
        except OSError:
            return
        for name in names:
            if not name.endswith(".json") and not name.endswith(".json.del"):
                continue
            path = os.path.join(self.dir_path, name)
            doc = self._read_doc(path)
            if doc is None:
                continue
            tenant_id, rules, pending_event = doc
            if not pending_event:
                # A tombstone left behind after a successful ledger append:
                # finish the delete.
                if name.endswith(".del"):
                    try:
                        os.unlink(path)
                    except OSError:
                        pass
                continue
            # A multi-file tenant restore transaction is resolved by the
            # RestoreCoordinator (its manifest drives the shared event).
            if isinstance(pending_event, dict) and pending_event.get("_restore"):
                continue
            event = AuditEvent.from_json(pending_event)
            if name.endswith(".json.del"):                # A delete tombstone. If the original file is still on disk the
                # crash happened before the unlink, so the delete never
                # happened: discard the tombstone without appending. Otherwise
                # finish the transaction (append is idempotent on event_id).
                original = path[: -len(".del")]
                if os.path.exists(original):
                    try:
                        os.unlink(path)
                    except OSError:
                        pass
                    continue
                self.audit.append(event)
                try:
                    os.unlink(path)
                except OSError:
                    pass
            else:
                # append() is idempotent on event_id.
                self.audit.append(event)
                self._write_atomic(
                    path,
                    {"tenant_id": tenant_id,
                     "rules": [r.to_json() for r in rules],
                     "pending_event": None},
                )

    def _commit_put(self, tenant_id: str, rules: List[Rule],
                    event: AuditEvent, existed: bool, previous: Optional[dict]):
        """Write a document and its event as one logical transaction."""
        path = self._path_for(tenant_id)
        doc = {
            "tenant_id": tenant_id,
            "rules": [r.to_json() for r in rules],
            "pending_event": event.to_json(),
        }
        self._write_atomic(path, doc)
        try:
            self.audit.append(event)
        except BaseException:
            if not existed:
                try:
                    os.unlink(path)
                except OSError:
                    pass
            elif previous is not None:
                self._write_atomic(path, previous)
            raise
        # The durable ledger append is the commit point; clearing the marker
        # is post-commit housekeeping. A failure here leaves the marker for
        # startup recovery and must never roll the document back or fail the
        # request.
        doc["pending_event"] = None
        try:
            self._write_atomic(path, doc)
        except OSError:
            pass

    # -- public API --------------------------------------------------------
    def get(self, tenant_id: str) -> Optional[List[Rule]]:
        """Return the tenant's rules, or None when no document exists."""
        doc = self._read_doc(self._path_for(tenant_id))
        if doc is None:
            return None
        return doc[1]

    def put(self, tenant_id: str, rules: List[Rule]) -> List[Rule]:
        """Replace (or create) the tenant's document and audit policy_update."""
        with self.tenant_lock(tenant_id):
            path = self._path_for(tenant_id)
            existed = os.path.exists(path)
            previous = None
            if existed:
                try:
                    with open(path, "r", encoding="utf-8") as fh:
                        previous = json.load(fh)
                except (OSError, ValueError) as exc:
                    raise LedgerError(
                        "cannot read policy document: %s" % exc
                    ) from exc
            event = self.audit.new_event(
                tenant_id, audit_mod.ACTION_POLICY_UPDATE, None,
                audit_mod.OUTCOME_SUCCESS,
            )
            self._commit_put(tenant_id, rules, event, existed, previous)
        return rules

    def delete(self, tenant_id: str) -> None:
        """Delete the tenant's document and audit policy_delete.

        Tombstone sequence: write a ``.json.del`` marker carrying the event,
        unlink the document, append the event, then remove the marker. A crash
        between any two steps is repaired on the next open. If the ledger
        append itself fails, the original document is restored byte-for-byte
        and the tombstone discarded, so a failed delete never takes effect.
        Deleting a tenant that has no document still records the event.
        """
        with self.tenant_lock(tenant_id):
            path = self._path_for(tenant_id)
            existed = os.path.exists(path)
            event = self.audit.new_event(
                tenant_id, audit_mod.ACTION_POLICY_DELETE, None,
                audit_mod.OUTCOME_SUCCESS,
            )
            if not existed:
                self.audit.append(event)
                return
            try:
                with open(path, "r", encoding="utf-8") as fh:
                    previous = json.load(fh)
            except (OSError, ValueError) as exc:
                raise LedgerError(
                    "cannot read policy document: %s" % exc
                ) from exc
            tombstone = path + ".del"
            self._write_atomic(
                tombstone,
                {"tenant_id": tenant_id, "rules": [],
                 "pending_event": event.to_json()},
            )
            os.unlink(path)
            try:
                # From here on a crash is repaired from the tombstone; the
                # append is idempotent on event_id.
                self.audit.append(event)
            except BaseException:
                # The ledger write failed: roll the delete back so the
                # document and its event never diverge.
                self._write_atomic(path, previous)
                try:
                    os.unlink(tombstone)
                except OSError:
                    pass
                raise
            try:
                os.unlink(tombstone)
            except OSError:
                pass

    def audit_read(self, tenant_id: str) -> None:
        """Record a successful policy_read (the document is never modified)."""
        event = self.audit.new_event(
            tenant_id, audit_mod.ACTION_POLICY_READ, None,
            audit_mod.OUTCOME_SUCCESS,
        )
        self.audit.append(event)

    def is_allowed(self, tenant_id: str, action: str, subject: str) -> bool:
        """Enforce the tenant document for (subject, action).

        No document means unrestricted. Otherwise deny wins, and an action no
        rule matches is denied.
        """
        rules = self.get(tenant_id)
        if rules is None:
            return True
        allowed = False
        for rule in rules:
            if rule.subject != subject or action not in rule.actions:
                continue
            if rule.effect == "deny":
                return False
            allowed = True
        return allowed

    # -- tenant restore hooks ---------------------------------------------
    def owner_of_path(self, path: str) -> Optional[str]:
        """Return the owning tenant_id recorded inside a policy file."""
        doc = self._read_doc(path)
        if doc is None:
            return None
        return doc[0]

    def write_restore_pending(
        self, tenant_id: str, rules: List[Rule], marker: dict
    ) -> None:
        """Atomically write a restored policy document carrying the marker.

        Used by the RestoreCoordinator; the caller guarantees no document
        exists for the tenant and holds the write lock.
        """
        self._write_atomic(
            self._path_for(tenant_id),
            {
                "tenant_id": tenant_id,
                "rules": [r.to_json() for r in rules],
                "pending_event": marker,
            },
        )

    def clear_restore_pending(self, tenant_id: str, rules: List[Rule]) -> None:
        """Rewrite a restored policy document without its pending marker."""
        self._write_atomic(
            self._path_for(tenant_id),
            {
                "tenant_id": tenant_id,
                "rules": [r.to_json() for r in rules],
                "pending_event": None,
            },
        )

    def remove_restore_file(self, tenant_id: str) -> None:
        """Delete a policy document written by a restore being rolled back."""
        try:
            os.unlink(self._path_for(tenant_id))
        except FileNotFoundError:
            pass

"""Cryptographic key generation for supported algorithms."""

import base64
import os
from typing import NamedTuple, Optional

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa

SUPPORTED_ALGORITHMS = ("AES256", "RSA2048")


class GeneratedKey(NamedTuple):
    """Result of generating a key.

    public_material is PEM (SubjectPublicKeyInfo) for RSA, None for AES.
    private_material stays server-side only (PEM for RSA, base64 for AES).
    """

    public_material: Optional[str]
    private_material: str


def _generate_aes256() -> GeneratedKey:
    """Generate a 256-bit AES key (no public component)."""
    raw = os.urandom(32)
    return GeneratedKey(
        public_material=None,
        private_material=base64.b64encode(raw).decode("ascii"),
    )


def _generate_rsa2048() -> GeneratedKey:
    """Generate a 2048-bit RSA key pair."""
    private_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
    private_pem = private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption(),
    ).decode("ascii")
    public_pem = private_key.public_key().public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo,
    ).decode("ascii")
    return GeneratedKey(
        public_material=public_pem,
        private_material=private_pem,
    )


def generate_key(algorithm: str) -> GeneratedKey:
    """Generate a new key for the given algorithm name."""
    if algorithm == "AES256":
        return _generate_aes256()
    if algorithm == "RSA2048":
        return _generate_rsa2048()
    raise ValueError("unsupported algorithm: %r" % (algorithm,))

"""Envelope encryption for tenant keys (format keymgr-envelope-v1).

A fresh 256-bit data key (DEK) seals the plaintext with AES-256-GCM; the DEK is
then wrapped by the named key version (the key-encryption key, KEK):

* ``AES256`` KEK: the DEK is wrapped with AES-256-GCM (wrap scheme
  ``AES-GCM``);
* ``RSA2048`` KEK: the DEK is wrapped with RSA-OAEP-SHA256
  (``RSA-OAEP-SHA256``).

The envelope is one base64 token whose JSON payload carries only metadata and
wrapped material: ``key_id``, ``version``, the algorithm/schemes, the GCM
nonce/tag/ciphertext, the wrapped DEK and the authenticated AAD. Raw private
keys, data keys and passphrases never enter the envelope; the data key exists
only in process memory for the duration of one call.
"""

import base64
import binascii
import json
import os
from dataclasses import dataclass
from typing import Optional

from cryptography.exceptions import InvalidTag
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding, rsa
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

FORMAT = "keymgr-envelope-v1"

# Content encryption is always AES-256-GCM under the ephemeral data key.
ENC_AES_GCM = "AES-GCM"
# KEK wrap schemes.
WRAP_AES_GCM = "AES-GCM"
WRAP_RSA_OAEP_SHA256 = "RSA-OAEP-SHA256"

_AES256 = "AES256"
_RSA2048 = "RSA2048"
_KEY_LEN = 32
_NONCE_LEN = 12
_TAG_LEN = 16
_RSA_WRAP_LEN = 256  # RSA-2048 OAEP ciphertext length.

_OAEP = padding.OAEP(
    mgf=padding.MGF1(algorithm=hashes.SHA256()),
    algorithm=hashes.SHA256(),
    label=None,
)


class EnvelopeError(ValueError):
    """An envelope request failure (always surfaced as 400)."""


@dataclass(frozen=True)
class OpenedEnvelope:
    """Structurally validated, still-encrypted envelope contents."""

    key_id: str
    version: int
    algorithm: str
    enc: str
    wrap: str
    nonce: bytes
    tag: bytes
    ciphertext: bytes
    wrapped_key: bytes
    wrap_nonce: Optional[bytes]
    aad: bytes


def b64_decode_field(value, field: str) -> bytes:
    """Strictly decode standard base64 (padding required).

    Raises EnvelopeError naming the request field on any non-string or
    non-canonical input.
    """
    if not isinstance(value, str):
        raise EnvelopeError("field %s must be a base64 string" % field)
    if value == "":
        return b""
    try:
        raw = base64.b64decode(value.encode("ascii"), validate=True)
    except (ValueError, TypeError, binascii.Error) as exc:
        raise EnvelopeError(
            "field %s is not valid base64" % field
        ) from exc
    return raw


def b64_encode(raw: bytes) -> str:
    """Canonical standard base64 encoding used for every envelope token."""
    return base64.b64encode(raw).decode("ascii")


def _wrap_dek(algorithm: str, kek) -> tuple:
    """Wrap a fresh 32-byte DEK under the KEK. Returns (dek, wk, wrap_nonce)."""
    dek = os.urandom(_KEY_LEN)
    if algorithm == _AES256:
        if not isinstance(kek, (bytes, bytearray)) or len(kek) != _KEY_LEN:
            raise EnvelopeError("server key material is invalid for AES256")
        wrap_nonce = os.urandom(_NONCE_LEN)
        sealed = AESGCM(bytes(kek)).encrypt(wrap_nonce, dek, None)
        return dek, sealed, wrap_nonce
    if algorithm == _RSA2048:
        if not isinstance(kek, rsa.RSAPrivateKey) or kek.key_size != 2048:
            raise EnvelopeError(
                "server key material is invalid for RSA2048"
            )
        sealed = kek.public_key().encrypt(dek, _OAEP)
        return dek, sealed, None
    raise EnvelopeError("unsupported algorithm for envelope: %r" % algorithm)


def _unwrap_dek(opened: "OpenedEnvelope", kek) -> bytes:
    """Recover the DEK from the envelope using the KEK."""
    try:
        if opened.algorithm == _AES256:
            if not isinstance(kek, (bytes, bytearray)) or len(kek) != _KEY_LEN:
                raise EnvelopeError(
                    "server key material is invalid for AES256"
                )
            if opened.wrap_nonce is None:
                raise InvalidTag("missing wrap nonce")
            return AESGCM(bytes(kek)).decrypt(
                opened.wrap_nonce, opened.wrapped_key, None
            )
        if opened.algorithm == _RSA2048:
            if not isinstance(kek, rsa.RSAPrivateKey) or kek.key_size != 2048:
                raise EnvelopeError(
                    "server key material is invalid for RSA2048"
                )
            return kek.decrypt(opened.wrapped_key, _OAEP)
    except InvalidTag as exc:
        raise EnvelopeError(
            "field envelope is tampered or cannot be authenticated"
        ) from exc
    except ValueError as exc:
        # RSA decryption failures (wrong key/size/padding) land here.
        raise EnvelopeError(
            "field envelope is tampered or cannot be authenticated"
        ) from exc
    raise EnvelopeError(
        "field envelope is tampered or cannot be authenticated"
    )


def encode_envelope(
    *,
    key_id: str,
    version: int,
    algorithm: str,
    kek,
    plaintext: bytes,
    aad: Optional[bytes] = None,
) -> str:
    """Seal plaintext under a fresh data key wrapped by the KEK.

    Returns the opaque base64 envelope token. The KEK is the raw 32-byte key
    for AES256 or a loaded 2048-bit RSA private key for RSA2048 (its public
    component wraps the DEK).
    """
    if aad is None:
        aad = b""
    dek, wrapped_key, wrap_nonce = _wrap_dek(algorithm, kek)
    nonce = os.urandom(_NONCE_LEN)
    sealed = AESGCM(dek).encrypt(nonce, plaintext, aad)
    ciphertext, tag = sealed[:-_TAG_LEN], sealed[-_TAG_LEN:]
    wrap = WRAP_AES_GCM if algorithm == _AES256 else WRAP_RSA_OAEP_SHA256
    payload = {
        "format": FORMAT,
        "key_id": key_id,
        "version": version,
        "algorithm": algorithm,
        "enc": ENC_AES_GCM,
        "wrap": wrap,
        "nonce": b64_encode(nonce),
        "tag": b64_encode(tag),
        "ciphertext": b64_encode(ciphertext),
        "wrapped_key": b64_encode(wrapped_key),
        "aad": b64_encode(aad),
    }
    if wrap_nonce is not None:
        payload["wrap_nonce"] = b64_encode(wrap_nonce)
    raw = json.dumps(
        payload, separators=(",", ":"), sort_keys=True
    ).encode("utf-8")
    return b64_encode(raw)


def _require_str(obj: dict, name: str) -> str:
    value = obj.get(name)
    if not isinstance(value, str) or not value:
        raise EnvelopeError("field envelope has missing or invalid %s" % name)
    return value


def _require_b64(obj: dict, name: str, *, allow_empty: bool = False) -> bytes:
    value = obj.get(name)
    if not isinstance(value, str):
        raise EnvelopeError("field envelope has missing or invalid %s" % name)
    if not value and not allow_empty:
        raise EnvelopeError("field envelope has missing or invalid %s" % name)
    try:
        return base64.b64decode(value.encode("ascii"), validate=True)
    except (ValueError, TypeError, binascii.Error) as exc:
        raise EnvelopeError(
            "field envelope has invalid base64 in %s" % name
        ) from exc


def decode_envelope(token: str) -> OpenedEnvelope:
    """Parse and structurally validate an envelope token (no crypto).

    Raises EnvelopeError (surfaced as 400) naming ``field envelope`` for any
    malformed, truncated, tampered-shape or unsupported-format token.
    """
    if not isinstance(token, str) or not token:
        raise EnvelopeError("field envelope must be a non-empty string")
    try:
        raw = base64.b64decode(token.encode("ascii"), validate=True)
    except (ValueError, TypeError, binascii.Error) as exc:
        raise EnvelopeError("field envelope is not valid base64") from exc
    try:
        obj = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise EnvelopeError(
            "field envelope does not contain a valid JSON object"
        ) from exc
    if not isinstance(obj, dict):
        raise EnvelopeError(
            "field envelope does not contain a valid JSON object"
        )
    if obj.get("format") != FORMAT:
        raise EnvelopeError("field envelope format must be %r" % FORMAT)
    key_id = _require_str(obj, "key_id")
    version = obj.get("version")
    if (
        not isinstance(version, int)
        or isinstance(version, bool)
        or version < 1
    ):
        raise EnvelopeError(
            "field envelope version must be a positive integer"
        )
    algorithm = obj.get("algorithm")
    if algorithm not in (_AES256, _RSA2048):
        raise EnvelopeError(
            "field envelope algorithm must be one of: AES256, RSA2048"
        )
    expected_wrap = (
        WRAP_AES_GCM if algorithm == _AES256 else WRAP_RSA_OAEP_SHA256
    )
    if obj.get("enc") != ENC_AES_GCM:
        raise EnvelopeError("field envelope enc must be %r" % ENC_AES_GCM)
    if obj.get("wrap") != expected_wrap:
        raise EnvelopeError(
            "field envelope wrap must be %r for algorithm %s"
            % (expected_wrap, algorithm)
        )
    nonce = _require_b64(obj, "nonce")
    tag = _require_b64(obj, "tag")
    if len(nonce) != _NONCE_LEN:
        raise EnvelopeError("field envelope nonce must be 12 bytes")
    if len(tag) != _TAG_LEN:
        raise EnvelopeError("field envelope tag must be 16 bytes")
    ciphertext = _require_b64(obj, "ciphertext", allow_empty=True)
    wrapped_key = _require_b64(obj, "wrapped_key")
    wrap_nonce = None
    if algorithm == _AES256:
        wrap_nonce = _require_b64(obj, "wrap_nonce")
        if len(wrap_nonce) != _NONCE_LEN:
            raise EnvelopeError(
                "field envelope wrap_nonce must be 12 bytes"
            )
        # AES-GCM of a 32-byte DEK is exactly 48 bytes (32 + 16 tag).
        if len(wrapped_key) != _KEY_LEN + _TAG_LEN:
            raise EnvelopeError(
                "field envelope wrapped_key has an invalid length"
            )
    else:
        if len(wrapped_key) != _RSA_WRAP_LEN:
            raise EnvelopeError(
                "field envelope wrapped_key has an invalid length"
            )
        if "wrap_nonce" in obj and obj["wrap_nonce"] is not None:
            raise EnvelopeError(
                "field envelope wrap_nonce must be absent for RSA2048"
            )
    aad = b""
    if "aad" in obj and obj["aad"] is not None:
        aad = _require_b64(obj, "aad", allow_empty=True)
    return OpenedEnvelope(
        key_id=key_id,
        version=version,
        algorithm=algorithm,
        enc=ENC_AES_GCM,
        wrap=expected_wrap,
        nonce=nonce,
        tag=tag,
        ciphertext=ciphertext,
        wrapped_key=wrapped_key,
        wrap_nonce=wrap_nonce,
        aad=aad,
    )


def open_envelope(opened: OpenedEnvelope, kek) -> bytes:
    """Unwrap the data key and decrypt the payload (AES/RSA KEK).

    A wrong key version, a modified nonce/tag/ciphertext/wrapped_key or a
    failed RSA unpadding all fail as one field-naming authentication error;
    the caller separately checks that the request AAD equals the envelope AAD.
    """
    dek = _unwrap_dek(opened, kek)
    try:
        sealed = opened.ciphertext + opened.tag
        return AESGCM(dek).decrypt(opened.nonce, sealed, opened.aad)
    except InvalidTag as exc:
        raise EnvelopeError(
            "field envelope is tampered or cannot be authenticated"
        ) from exc

"""KMS/HSM provider abstraction.

Every private key is owned by a *provider*: a local software key store by
default, or an external KMS/HSM reached through the ``module:factory`` entry
point named by ``KEYMGR_PROVIDER``. The rest of the package never touches raw
key material when a provider is in use: it only persists the opaque
``provider_id`` / ``handle`` / ``encrypted_material`` triple a provider
returns, and asks the provider to turn a handle back into exportable material.

Primary/standby failover
------------------------
``KEYMGR_PROVIDER_CHAIN`` may name a comma-separated list of ``local`` /
``module:factory`` entries (entries and their built ``provider_id`` values
must be unique; an unset variable falls back to ``KEYMGR_PROVIDER``, while a
set-but-empty, empty-item or malformed chain is unusable). The first healthy
entry is activated. Every ORDINARY provider call then shares ONE
non-resettable five-second budget started at its first wait or probe: every
gate wait and every health probe of the attempt draws on the same deadline,
and a single ``health()`` probe is additionally capped at one second. A probe
returning exactly ``True`` clears the persisted failure count and proceeds;
``False``, a non-bool, a raised probe, one past its wait, or a result that
arrives only after the wait (void -- it never counts as anything but the
timeout) increments the active entry's persisted failure count (capped at
three) and pins the call to the fixed 503. The first two failures never
switch; after the third failure the call uses the REMAINDER of the same
five-second budget to re-verify the active entry (still at most one second
per probe) -- recovery clears the count and serves the call -- and otherwise
probes the standby entries in chain order under the same cross-process
intent/drain gate a reconnect uses, failing over exactly once to the first
healthy standby (a single ``switching`` then ``ready`` commit, generation
plus one) and continuing in the new generation. Old calls finish on the
instance they captured, later calls land on the new generation, and
concurrent third strikes build/commit exactly once. With no healthy standby
(or on a gate timeout) the old generation is retained. The threshold lives in
``provider-health.json`` (a 0600 satellite of a READY ``provider-state.json``
with the same id and generation), so it survives restarts and is shared
across processes; a corrupt, ahead or same-generation-wrong-id health record
is a fixed 503 that is never rewritten. A recovered primary is never
re-selected automatically; only ``reconnect`` re-selects the first healthy
entry, while ``switchover`` moves the active provider to one NAMED chain
entry under the same gate (``switching`` then ``ready`` commits, reason
``reconnect``). Pending idempotent operations stay bound to their original
``provider_id`` and are never replayed on a standby.

Provider contract
-----------------
A provider instance exposes:

* ``provider_id``: a non-empty string;
* ``capabilities``: ``{"algorithms": ["AES256", "RSA2048"],
  "operations": ["generate", "rotate", "import_material",
  "export_material", "delete"]}``;
* ``generate(algorithm)`` / ``rotate(algorithm)`` ->
  ``{"handle", "public_key", "encrypted_material"}``;
* ``import_material(algorithm, public_key, material)`` -> the same triple;
* ``export_material(handle)`` -> ``{"public_key", "encrypted_material"}``;
* ``delete(handle)`` -> ``None``, idempotent;
* ``health()`` -> ``bool``, *optional*. A missing method is treated as ready;
  a method that raises or returns anything but a real bool reports unavailable.
  The probe's own text never leaves the process.

The factory named by ``KEYMGR_PROVIDER=module:factory`` is imported lazily on
first use and called with no arguments. A missing module/factory, a factory
raising, or a returned object failing the contract all raise
:class:`ProviderUnavailable`; the service answers ``503`` (CLI exit ``1``) and
never falls back to the local provider.
"""

import base64
import errno
import importlib
import json
import os
import tempfile
import threading
import time
import uuid
from contextlib import contextmanager
from typing import List, NamedTuple, Optional, Tuple

try:  # fcntl is POSIX-only; the cross-process gate degrades to in-process.
    import fcntl
except ImportError:  # pragma: no cover - non-POSIX platforms
    fcntl = None

from cryptography.exceptions import UnsupportedAlgorithm
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

from .crypto import SUPPORTED_ALGORITHMS, generate_key

#: Default provider id and the id of the built-in software provider.
LOCAL_PROVIDER_ID = "local"

OP_GENERATE = "generate"
OP_ROTATE = "rotate"
OP_IMPORT_MATERIAL = "import_material"
OP_EXPORT_MATERIAL = "export_material"
OP_DELETE = "delete"
OPERATIONS = (
    OP_GENERATE,
    OP_ROTATE,
    OP_IMPORT_MATERIAL,
    OP_EXPORT_MATERIAL,
    OP_DELETE,
)

_DEK_NAME = "local.dek"
_REGISTRY_NAME = "local-registry.json"
# Prefix for material wrapped by the local DEK; never reused for another
# encoding so wrapped blobs are self-describing on disk.
_WRAP_PREFIX = "pev1."
_NONCE_LEN = 12


class ProviderError(Exception):
    """Base class for provider failures."""


class ProviderUnavailable(ProviderError):
    """The provider cannot service the request (load/backend/handle failure).

    Surfaced as HTTP ``503`` / CLI exit code ``1``. The message is logged
    server-side; clients only ever see a generic status (handles and material
    never leave the boundary).
    """


class ProviderInvalidMaterial(ProviderError):
    """Material handed to the provider is malformed for the algorithm.

    Surfaced as HTTP ``400`` / CLI exit code ``2``; the message names the
    offending field but never embeds the material itself.
    """


class ProviderSwitchoverInvalid(ProviderError):
    """A switchover request names no usable chain target.

    Raised when no provider chain is configured or the requested
    ``provider_id`` is not one of the chain entries. Surfaced as HTTP
    ``400`` / CLI exit code ``2`` with the field named, and raised before
    any state write, provider swap or audit event (zero side effects).
    """


class MaterialTriple(NamedTuple):
    """The provider-owned result of generate/rotate/import_material."""

    handle: str
    public_key: Optional[str]
    encrypted_material: str


class ExportedMaterial(NamedTuple):
    """Result of export_material: material plus its public component."""

    public_key: Optional[str]
    encrypted_material: str


def _b64e(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _b64d(text: str) -> bytes:
    return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))


def _require_triple(result, operation: str) -> MaterialTriple:
    """Validate a generate/rotate/import result has a handle and material."""
    if not isinstance(result, dict):
        raise ProviderUnavailable(
            "provider %s returned a non-object from %s"
            % ("external", operation)
        )
    handle = result.get("handle")
    material = result.get("encrypted_material")
    if not isinstance(handle, str) or not handle:
        raise ProviderUnavailable(
            "provider returned an empty handle from %s" % operation
        )
    if not isinstance(material, str) or not material:
        raise ProviderUnavailable(
            "provider returned empty encrypted_material from %s" % operation
        )
    public_key = result.get("public_key")
    if public_key is not None and not isinstance(public_key, str):
        raise ProviderUnavailable(
            "provider returned an invalid public_key from %s" % operation
        )
    return MaterialTriple(
        handle=handle, public_key=public_key, encrypted_material=material
    )


class KeyProvider:
    """Abstract provider; concrete providers implement the five operations."""

    provider_id = ""
    capabilities = {"algorithms": (), "operations": ()}

    def configure(self, data_dir: str) -> None:
        """Bind any persistent state to the data directory (optional)."""

    def generate(self, algorithm: str) -> MaterialTriple:
        raise NotImplementedError

    def rotate(self, algorithm: str) -> MaterialTriple:
        raise NotImplementedError

    def import_material(
        self,
        algorithm: str,
        public_key: Optional[str],
        material: str,
    ) -> MaterialTriple:
        raise NotImplementedError

    def export_material(self, handle: str) -> ExportedMaterial:
        raise NotImplementedError

    def delete(self, handle: str) -> None:
        raise NotImplementedError

    def health(self) -> bool:
        """Optional KMS/HSM readiness probe.

        Built-in providers are always ready. An external provider may omit
        this method (a missing probe means healthy); :class:`_SafeProvider`
        enforces the bool/exception contract on objects that supply one.
        """
        return True

    def supports(self, algorithm: str, operation: str) -> bool:
        caps = getattr(self, "capabilities", {}) or {}
        return (
            algorithm in caps.get("algorithms", ())
            and operation in caps.get("operations", ())
        )


def _validate_external(obj) -> None:
    """Check a factory-built object satisfies the provider contract."""
    provider_id = getattr(obj, "provider_id", None)
    if not isinstance(provider_id, str) or not provider_id:
        raise ProviderUnavailable(
            "provider factory returned an object without a non-empty provider_id"
        )
    caps = getattr(obj, "capabilities", None)
    if not isinstance(caps, dict):
        raise ProviderUnavailable(
            "provider %r has no capabilities mapping" % provider_id
        )
    algorithms = caps.get("algorithms")
    operations = caps.get("operations")
    if not isinstance(algorithms, (list, tuple)) or not isinstance(
        operations, (list, tuple)
    ):
        raise ProviderUnavailable(
            "provider %r capabilities must list algorithms and operations"
            % provider_id
        )
    missing = [a for a in SUPPORTED_ALGORITHMS if a not in algorithms]
    if missing:
        raise ProviderUnavailable(
            "provider %r lacks required algorithms: %s"
            % (provider_id, ", ".join(missing))
        )
    missing_ops = [op for op in OPERATIONS if op not in operations]
    if missing_ops:
        raise ProviderUnavailable(
            "provider %r lacks required operations: %s"
            % (provider_id, ", ".join(missing_ops))
        )
    for name in OPERATIONS:
        if not callable(getattr(obj, name, None)):
            raise ProviderUnavailable(
                "provider %r is missing a callable %s() operation"
                % (provider_id, name)
            )
    configure = getattr(obj, "configure", None)
    if configure is not None and not callable(configure):
        raise ProviderUnavailable(
            "provider %r has a non-callable configure attribute" % provider_id
        )
    # health() is optional: no attribute means always healthy. A present but
    # non-callable health is a contract failure like any other method.
    health = getattr(obj, "health", None)
    if health is not None and not callable(health):
        raise ProviderUnavailable(
            "provider %r has a non-callable health attribute" % provider_id
        )


class _SafeProvider:
    """Adapter around an external provider enforcing the error contract.

    ProviderError subtypes pass through unchanged; any other exception the
    external module raises is normalized to ProviderUnavailable so a backend
    fault always surfaces as 503 and never as a 500 or a fallback.
    """

    def __init__(self, inner) -> None:
        self._inner = inner
        self.provider_id = inner.provider_id
        self.capabilities = inner.capabilities

    def configure(self, data_dir: str) -> None:
        try:
            configure = getattr(self._inner, "configure", None)
            if configure is not None:
                configure(data_dir)
        except ProviderError:
            raise
        except Exception as exc:
            raise ProviderUnavailable(
                "provider %r failed to initialize" % self.provider_id
            ) from exc

    def _call(self, name: str, *args):
        method = getattr(self._inner, name)
        try:
            return method(*args)
        except ProviderError:
            raise
        except Exception as exc:
            raise ProviderUnavailable(
                "provider %r operation %s failed" % (self.provider_id, name)
            ) from exc

    def generate(self, algorithm: str) -> MaterialTriple:
        return _require_triple(self._call("generate", algorithm), "generate")

    def rotate(self, algorithm: str) -> MaterialTriple:
        return _require_triple(self._call("rotate", algorithm), "rotate")

    def import_material(self, algorithm, public_key, material) -> MaterialTriple:
        return _require_triple(
            self._call("import_material", algorithm, public_key, material),
            "import_material",
        )

    def export_material(self, handle: str) -> ExportedMaterial:
        result = self._call("export_material", handle)
        if not isinstance(result, dict):
            raise ProviderUnavailable(
                "provider returned a non-object from export_material"
            )
        material = result.get("encrypted_material")
        if not isinstance(material, str) or not material:
            raise ProviderUnavailable(
                "provider returned empty encrypted_material from export_material"
            )
        public_key = result.get("public_key")
        if public_key is not None and not isinstance(public_key, str):
            raise ProviderUnavailable(
                "provider returned an invalid public_key from export_material"
            )
        return ExportedMaterial(
            public_key=public_key, encrypted_material=material
        )

    def delete(self, handle: str) -> None:
        # Idempotent by contract; even so, a backend fault on delete is a 503
        # (the caller may retry, and delete must remain idempotent).
        self._call("delete", handle)

    def health(self) -> bool:
        """Optional readiness probe normalized to a bool.

        A provider without a ``health`` method is treated as ready. A method
        that raises, returns a non-bool, or returns ``False`` reports
        unavailable; any backend text is swallowed here and never reaches a
        client.
        """
        method = getattr(self._inner, "health", None)
        if method is None:
            # Missing health() means healthy by contract.
            return True
        try:
            result = method()
        except Exception:
            return False
        # Only the exact bool True is healthy; a bool False, a truthy
        # non-bool (1, "yes", ...) and any other object mean unavailable.
        return result is True


class LocalProvider(KeyProvider):
    """Built-in software provider.

    Raw material never lands in a key file: each generated/imported key is
    wrapped with AES-256-GCM under a data-encryption key kept in
    ``local.dek`` (0600), and only the wrapped blob plus an opaque handle is
    persisted. A small registry (``local-registry.json``, 0600) maps each
    handle to its algorithm and wrapped blob, so ``export_material(handle)``
    can re-derive the raw material and ``delete`` stays idempotent. The
    registry stores only DEK-wrapped material, never plaintext.
    """

    provider_id = LOCAL_PROVIDER_ID
    capabilities = {
        "algorithms": tuple(SUPPORTED_ALGORITHMS),
        "operations": OPERATIONS,
    }

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._data_dir: Optional[str] = None
        self._dek: Optional[bytes] = None
        self._registry: dict = {}
        self._configured = False

    # -- state -------------------------------------------------------------
    def configure(self, data_dir: str) -> None:
        with self._lock:
            if self._configured and self._data_dir == data_dir:
                return
            os.makedirs(data_dir, exist_ok=True)
            self._data_dir = data_dir
            self._dek = self._load_or_create_dek(data_dir)
            self._registry = self._load_registry(data_dir)
            self._configured = True

    @staticmethod
    def _load_or_create_dek(data_dir: str) -> bytes:
        path = os.path.join(data_dir, _DEK_NAME)
        try:
            with open(path, "rb") as fh:
                dek = fh.read()
            if len(dek) == 32:
                return dek
        except FileNotFoundError:
            pass
        except OSError as exc:
            raise ProviderUnavailable("cannot read local DEK: %s" % exc) from exc
        dek = os.urandom(32)
        try:
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            try:
                os.write(fd, dek)
                os.fsync(fd)
            finally:
                os.close(fd)
        except FileExistsError:
            with open(path, "rb") as fh:
                dek = fh.read()
        except OSError as exc:
            raise ProviderUnavailable("cannot write local DEK: %s" % exc) from exc
        if len(dek) != 32:
            raise ProviderUnavailable("local DEK file is corrupt")
        return dek

    @staticmethod
    def _load_registry(data_dir: str) -> dict:
        path = os.path.join(data_dir, _REGISTRY_NAME)
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except FileNotFoundError:
            return {}
        except (OSError, ValueError) as exc:
            raise ProviderUnavailable(
                "cannot read local handle registry: %s" % exc
            ) from exc
        if not isinstance(data, dict):
            raise ProviderUnavailable("local handle registry is corrupt")
        return data

    def _persist_registry_locked(self) -> None:
        path = os.path.join(self._data_dir, _REGISTRY_NAME)
        fd, tmp_path = tempfile.mkstemp(dir=self._data_dir, suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(self._registry, fh)
                fh.flush()
                os.fsync(fh.fileno())
            os.chmod(tmp_path, 0o600)
            os.replace(tmp_path, path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    def _require_configured(self) -> None:
        if not self._configured:
            raise ProviderUnavailable("local provider is not configured")

    # -- wrapping ----------------------------------------------------------
    def _wrap_locked(self, raw_material: str) -> str:
        nonce = os.urandom(_NONCE_LEN)
        ct = AESGCM(self._dek).encrypt(
            nonce, raw_material.encode("utf-8"), None
        )
        return _WRAP_PREFIX + _b64e(nonce) + "." + _b64e(ct)

    def _unwrap_locked(self, blob: str) -> str:
        if not isinstance(blob, str) or not blob.startswith(_WRAP_PREFIX):
            raise ProviderUnavailable("stored material is not a local blob")
        try:
            nonce_b, ct_b = blob[len(_WRAP_PREFIX):].split(".", 1)
            nonce = _b64d(nonce_b)
            ct = _b64d(ct_b)
            raw = AESGCM(self._dek).decrypt(nonce, ct, None)
            return raw.decode("utf-8")
        except Exception as exc:
            raise ProviderUnavailable(
                "cannot unwrap local material"
            ) from exc

    # -- material validation ----------------------------------------------
    @staticmethod
    def _validate_material(
        algorithm: str, public_key, material
    ):
        """Validate raw (legacy-shaped) material for an algorithm.

        AES material is base64 of exactly 32 bytes and has no public part;
        RSA material is a PEM private key of exactly 2048 bits, and the
        supplied public key (when present) must match it. Returns the parsed
        RSA private key (None for AES).
        """
        if not isinstance(material, str) or not material:
            raise ProviderInvalidMaterial(
                "field encrypted_material must be a non-empty string"
            )
        if algorithm == "AES256":
            if public_key is not None:
                raise ProviderInvalidMaterial(
                    "field public_key must be null for AES256"
                )
            try:
                raw = base64.b64decode(material, validate=True)
            except (ValueError, TypeError) as exc:
                raise ProviderInvalidMaterial(
                    "field encrypted_material must be valid base64 for AES256"
                ) from exc
            if len(raw) != 32:
                raise ProviderInvalidMaterial(
                    "field encrypted_material must decode to 32 bytes for AES256"
                )
            return None
        if algorithm == "RSA2048":
            try:
                private_key = serialization.load_pem_private_key(
                    material.encode("utf-8"), password=None
                )
            except (ValueError, TypeError, UnsupportedAlgorithm) as exc:
                raise ProviderInvalidMaterial(
                    "field encrypted_material must be a PEM private key for RSA2048"
                ) from exc
            if not isinstance(private_key, rsa.RSAPrivateKey) or (
                private_key.key_size != 2048
            ):
                raise ProviderInvalidMaterial(
                    "field encrypted_material must be a 2048-bit RSA private key"
                )
            if public_key is not None:
                if not isinstance(public_key, str) or not public_key:
                    raise ProviderInvalidMaterial(
                        "field public_key must be a PEM string for RSA2048"
                    )
                try:
                    supplied = serialization.load_pem_public_key(
                        public_key.encode("utf-8")
                    )
                    if not isinstance(supplied, rsa.RSAPublicKey):
                        raise ValueError("not an RSA public key")
                except (ValueError, TypeError, UnsupportedAlgorithm) as exc:
                    raise ProviderInvalidMaterial(
                        "field public_key must be a PEM RSA public key"
                    ) from exc
                expected = private_key.public_key().public_bytes(
                    encoding=serialization.Encoding.DER,
                    format=serialization.PublicFormat.SubjectPublicKeyInfo,
                )
                actual = supplied.public_bytes(
                    encoding=serialization.Encoding.DER,
                    format=serialization.PublicFormat.SubjectPublicKeyInfo,
                )
                if expected != actual:
                    raise ProviderInvalidMaterial(
                        "field public_key does not match the private key"
                    )
            return private_key
        raise ProviderInvalidMaterial(
            "unsupported value for field algorithm: %r (supported: %s)"
            % (algorithm, ", ".join(SUPPORTED_ALGORITHMS))
        )

    @staticmethod
    def _public_pem(private_key) -> str:
        return private_key.public_key().public_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PublicFormat.SubjectPublicKeyInfo,
        ).decode("ascii")

    def _adopt(
        self,
        algorithm: str,
        public_key,
        raw_material: str,
    ) -> MaterialTriple:
        """Validate raw material, wrap it under the DEK, mint a handle."""
        self._require_configured()
        private_key = self._validate_material(algorithm, public_key, raw_material)
        if algorithm == "RSA2048" and public_key is None:
            public_key = self._public_pem(private_key)
        handle = uuid.uuid4().hex
        with self._lock:
            wrapped = self._wrap_locked(raw_material)
            self._registry[handle] = {
                "algorithm": algorithm,
                "wrapped": wrapped,
            }
            self._persist_registry_locked()
        return MaterialTriple(
            handle=handle,
            public_key=public_key,
            encrypted_material=wrapped,
        )

    # -- KeyProvider operations -------------------------------------------
    def generate(self, algorithm: str) -> MaterialTriple:
        generated = generate_key(algorithm)
        return self._adopt(
            algorithm, generated.public_material, generated.private_material
        )

    def rotate(self, algorithm: str) -> MaterialTriple:
        # A rotated version is brand-new material owned by the same provider.
        return self.generate(algorithm)

    def import_material(
        self,
        algorithm: str,
        public_key,
        material: str,
    ) -> MaterialTriple:
        return self._adopt(algorithm, public_key, material)

    def export_material(self, handle: str) -> ExportedMaterial:
        """Return the raw bundle-shaped material for a registered handle.

        The registry keeps the DEK-wrapped blob, which is unwrapped here. The
        returned material is only ever sealed inside a passphrase-encrypted
        export bundle; an unknown handle is ProviderUnavailable.
        """
        self._require_configured()
        if not isinstance(handle, str) or not handle:
            raise ProviderUnavailable("export_material requires a handle")
        with self._lock:
            meta = self._registry.get(handle)
            if meta is None:
                raise ProviderUnavailable("unknown handle")
            algorithm = meta.get("algorithm")
            blob = meta.get("wrapped")
            try:
                raw = self._unwrap_locked(blob)
            except ProviderUnavailable:
                raise
        if algorithm == "AES256":
            return ExportedMaterial(public_key=None, encrypted_material=raw)
        try:
            private_key = serialization.load_pem_private_key(
                raw.encode("utf-8"), password=None
            )
        except (ValueError, TypeError, UnsupportedAlgorithm) as exc:
            raise ProviderUnavailable("stored local material is corrupt") from exc
        return ExportedMaterial(
            public_key=self._public_pem(private_key),
            encrypted_material=raw,
        )

    def delete(self, handle: str) -> None:
        """Drop a handle from the registry. Idempotent and never fails 404."""
        self._require_configured()
        with self._lock:
            if handle in self._registry:
                del self._registry[handle]
                self._persist_registry_locked()


# -- module:factory loading -------------------------------------------------
_provider_lock = threading.Lock()
_provider: Optional[KeyProvider] = None
_configured_dir: Optional[str] = None
_LOCAL_SINGLETON = LocalProvider()
# Every provider_id that has been the active instance (in this process, and
# historically in the data directory) is remembered. Lets a pending operation
# distinguish a reconnect that swapped in a different provider_id (keep the op
# pending) from a record owned by a provider that was never active here (the
# classic inactive-provider terminal 503).
_active_history: set = set()
_HISTORY_NAME = "provider-ids.json"


def _history_path() -> Optional[str]:
    if _configured_dir is None:
        return None
    return os.path.join(_configured_dir, _HISTORY_NAME)


def _load_history() -> None:
    path = _history_path()
    if path is None:
        return
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except FileNotFoundError:
        return
    except (OSError, ValueError):
        return
    ids = data.get("ids") if isinstance(data, dict) else None
    if isinstance(ids, list):
        _active_history.update(i for i in ids if isinstance(i, str) and i)


def _remember(provider_id: str) -> None:
    if not provider_id or provider_id in _active_history:
        return
    _active_history.add(provider_id)
    path = _history_path()
    if path is None:
        return
    ids = sorted(_active_history)
    fd, tmp_path = tempfile.mkstemp(dir=_configured_dir, suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            json.dump({"ids": ids}, fh)
            fh.flush()
            os.fsync(fh.fileno())
        os.chmod(tmp_path, 0o600)
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        # A history write failure never blocks provider selection; the set is
        # a best-effort hint, not an authority.


# -- non-disruptive reconnect gate -----------------------------------------
# Reconnect and ordinary provider calls share ONE five-second budget per
# attempt, measured from its FIRST wait or health probe. The ordering the gate
# enforces is:
#
#   1. a reconnect first establishes a cross-process *intent* (an exclusive
#      flock on ``provider-reconnect.lock``), THEN drains the calls admitted
#      before it;
#   2. every LATER call waits -- in every process -- from the instant intent
#      is visible until the candidate is built, contract-validated, health
#      probed, ``provider-state.json`` is committed and the swap finished;
#   3. calls admitted before the intent was established keep running on the
#      OLD provider instance they captured and are simply drained.
#
# The extra intent file is required because a blocking exclusive flock alone
# is NOT a barrier on Linux: new shared-lock requests leapfrog a queued
# exclusive waiter (verified on the host kernel), so later calls would slip
# past a reconnect that had only *queued* for ``provider-state.lock`` and a
# steady call stream could starve it. Ordinary calls therefore never hold the
# intent lock for their duration; they only probe it with an instant
# non-blocking shared trylock, once before and once after taking their shared
# state lease, and fall back to waiting when the probe catches a reconnect.
CALL_GATE_SECONDS = 5.0
_POLL_SECONDS = 0.02
#: Per-probe cap for a health probe on the ORDINARY call path. One attempt's
#: probes all draw on its single non-resettable :data:`CALL_GATE_SECONDS`
#: budget as well: a probe waits at most the smaller of one second and the
#: budget remainder, and a result landing only after that wait is void.
HEALTH_PROBE_SECONDS = 1.0


class _Budget:
    """The shared five-second budget for one call or reconnect attempt.

    The deadline starts lazily at the first blocking wait OR the first
    bounded health probe (``start`` is idempotent), so an attempt admitted
    without contention spends no budget on the gate itself; every later
    wait, poll and bounded probe shares one non-resettable deadline.
    """

    def __init__(self, seconds: Optional[float] = None) -> None:
        self.seconds = CALL_GATE_SECONDS if seconds is None else seconds
        self._deadline: Optional[float] = None

    def start(self) -> float:
        if self._deadline is None:
            self._deadline = time.monotonic() + self.seconds
        return self._deadline

    @property
    def deadline(self) -> float:
        return self.start()

    def remaining(self) -> float:
        return max(0.0, self.deadline - time.monotonic())

    def expired(self) -> bool:
        return self.remaining() <= 0


class ProviderReconnectPending(ProviderUnavailable):
    """A provider call blocked on the reconnect gate past the 5 s budget.

    Like every provider failure it answers 503 with the fixed generic body,
    but an idempotent operation bound when this is raised has made NO provider
    call: the guard leaves it PENDING (mirror and binding intact, no audit
    event), so a retry once reconnect settles continues under the same
    operation_id/event_id rather than being frozen as a terminal failure.
    """


class ProviderIdentityMismatch(ProviderReconnectPending):
    """A record/pending attempt is bound to a provider_id that is not active.

    Raised while a reconnect has installed a provider with a *different*
    ``provider_id`` and an idempotent operation still owed to the old id is
    being continued. The idempotent guard leaves the operation PENDING (never
    terminal) and answers 503, so that reconnecting a provider with the same
    id lets the same request/event continue exactly once.
    """


# -- committed cross-process provider state ---------------------------------
# ``provider-state.json`` (0600) is the single cross-process record of which
# provider is active in a data directory and which generation of it was last
# committed. It is written atomically (temp file, fsync, rename) by the first
# healthy activation, by every successful reconnect and by the two commits of
# every provider switch, as compact UTF-8 JSON with the fixed key order
# ``schema_version,provider_id,target_provider_id,generation,reason,phase``,
# no ASCII escaping and no trailing newline: schema_version is the fixed
# integer 2, provider_id a non-empty string, target_provider_id null or a
# non-empty string, generation a positive integer, reason one of
# ``initial``/``reconnect``/``failover`` and phase ``ready``/``switching``. A
# switch (a failover, or a reconnect that changes provider_id) first commits
# ``switching`` (old id, target id, the ORIGINAL generation) and only then
# ``ready`` (target id, null, generation+1), so a crash between the two
# commits never moves the generation. A process that reads ``switching``
# re-verifies the target: a healthy target completes the switch, anything
# else keeps the file byte-for-byte and answers the fixed 503. A legacy
# schema_version 1 file (no target/reason/phase) reads as ``ready``. A
# missing file is created by the first healthy activation (generation 1); a
# corrupt or invalid file poisons provider calls and reconnect (fixed 503)
# and is never rewritten.
_STATE_NAME = "provider-state.json"
_STATE_LOCK_NAME = "provider-state.lock"
# The reconnect-intent fence: a reconnect holds this lock exclusively for its
# whole drain/build/commit/swap window, while ordinary calls only ever touch
# it with an instant non-blocking shared trylock (never hold it across their
# work). A granted intent therefore becomes immediately visible to every later
# call in every process, regardless of flock's unfair read-leapfrog.
_INTENT_LOCK_NAME = "provider-reconnect.lock"
_STATE_SCHEMA_VERSION = 2
_STATE_LEGACY_SCHEMA_VERSION = 1
_REASON_INITIAL = "initial"
_REASON_RECONNECT = "reconnect"
_REASON_FAILOVER = "failover"
_REASONS = (_REASON_INITIAL, _REASON_RECONNECT, _REASON_FAILOVER)
_PHASE_READY = "ready"
_PHASE_SWITCHING = "switching"


class _CommittedState(NamedTuple):
    """A parsed ``provider-state.json`` record.

    ``reason`` is None only for a legacy schema_version 1 file (which has no
    target/reason/phase fields and is treated as ``ready``).
    """

    provider_id: str
    target_provider_id: Optional[str]
    generation: int
    reason: Optional[str]
    phase: str

# The (provider_id, generation) this process's cached ``_provider`` instance
# was activated/adopted/committed with. Only ever set together with
# ``_provider``; a commit observed on disk that does not match this tuple
# forces a rebuild on the next provider call.
_active_state: Optional[Tuple[str, int]] = None
# Serializes state sync/activation/adoption within this process. Lock order:
# ``_state_sync_lock`` -> state lock file -> ``_provider_lock`` (never the
# reverse), so a thread upgrading to the exclusive file lease can never
# deadlock against one holding the provider lock.
_state_sync_lock = threading.Lock()


def _state_path() -> Optional[str]:
    if _configured_dir is None:
        return None
    return os.path.join(_configured_dir, _STATE_NAME)


def _read_committed_state() -> Optional[_CommittedState]:
    """Return the committed state, or None if the state file is absent.

    A corrupt or field-invalid ``provider-state.json`` raises
    :class:`ProviderUnavailable`: provider calls and reconnect then answer
    the fixed 503 text and the file is left byte-for-byte untouched.
    """
    path = _state_path()
    if path is None:
        return None
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise ProviderUnavailable(
            "cannot read provider state: %s" % exc
        ) from exc
    try:
        data = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise ProviderUnavailable("provider state file is corrupt") from exc
    state = _parse_committed_state(data)
    if state is None:
        raise ProviderUnavailable("provider state file is corrupt")
    return state


def _parse_committed_state(data) -> Optional[_CommittedState]:
    """Validate a decoded state object; None when any field is invalid."""
    if not isinstance(data, dict):
        return None
    keys = set(data)
    if keys == {"schema_version", "provider_id", "generation"}:
        # Legacy schema_version 1: no target/reason/phase; treated as ready.
        version = data["schema_version"]
        provider_id = data["provider_id"]
        generation = data["generation"]
        if (
            type(version) is int
            and version == _STATE_LEGACY_SCHEMA_VERSION
            and isinstance(provider_id, str)
            and bool(provider_id)
            and type(generation) is int
            and generation >= 1
        ):
            return _CommittedState(
                provider_id=provider_id,
                target_provider_id=None,
                generation=generation,
                reason=None,
                phase=_PHASE_READY,
            )
        return None
    if keys != {
        "schema_version",
        "provider_id",
        "target_provider_id",
        "generation",
        "reason",
        "phase",
    }:
        return None
    version = data["schema_version"]
    provider_id = data["provider_id"]
    target = data["target_provider_id"]
    generation = data["generation"]
    reason = data["reason"]
    phase = data["phase"]
    if not (
        type(version) is int
        and version == _STATE_SCHEMA_VERSION
        and isinstance(provider_id, str)
        and bool(provider_id)
        and (target is None or (isinstance(target, str) and bool(target)))
        and type(generation) is int
        and generation >= 1
        and reason in _REASONS
        and phase in (_PHASE_READY, _PHASE_SWITCHING)
    ):
        return None
    # ready carries no target; switching always names its target.
    if phase == _PHASE_READY and target is not None:
        return None
    if phase == _PHASE_SWITCHING and not target:
        return None
    return _CommittedState(
        provider_id=provider_id,
        target_provider_id=target,
        generation=generation,
        reason=reason,
        phase=phase,
    )


def _assert_health_allows_commit(
    provider_id: str, generation: int
) -> None:
    """Refuse a provider-state commit that would overwrite a poison satellite.

    Called immediately before every ``provider-state.json`` commit. The
    existing health file may be superseded only when it is absent, lags the
    record being committed, or already tracks that same id/generation. A
    corrupt file, one ahead of the committed generation, or one at the same
    generation with a different provider_id is poison: raise the fixed 503 and
    leave BOTH files byte-for-byte untouched. This makes the corruption
    contract hold for reconnect/switchover/failover commits too, not just
    ordinary calls.
    """
    if _configured_dir is None:
        return
    health = _read_health()
    if health is None:
        return
    if health.generation < generation:
        return
    if health.generation == generation and health.provider_id == provider_id:
        return
    raise ProviderUnavailable(
        "provider health record is corrupt, ahead of the committed provider "
        "state, or tracks a different provider id"
    )


def _write_committed_state(
    provider_id: str,
    generation: int,
    reason: str,
    target_provider_id: Optional[str] = None,
    phase: str = _PHASE_READY,
) -> None:
    """Atomically commit ``provider-state.json`` (0600, fsync + rename).

    The payload is compact UTF-8 JSON with the fixed key order
    ``schema_version,provider_id,target_provider_id,generation,reason,phase``,
    non-ASCII written as-is and no trailing newline. The rename is the commit
    point: a crash before it keeps the previous record. A poison
    ``provider-health.json`` (corrupt/ahead/same-generation-wrong-id) blocks
    the commit before anything is written.
    """
    if _configured_dir is None:
        return
    _assert_health_allows_commit(provider_id, generation)
    payload = json.dumps(
        {
            "schema_version": _STATE_SCHEMA_VERSION,
            "provider_id": provider_id,
            "target_provider_id": target_provider_id,
            "generation": generation,
            "reason": reason,
            "phase": phase,
        },
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode("utf-8")
    try:
        fd, tmp_path = tempfile.mkstemp(dir=_configured_dir, suffix=".tmp")
    except OSError as exc:
        raise ProviderUnavailable(
            "cannot write provider state: %s" % exc
        ) from exc
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(payload)
            fh.flush()
            os.fsync(fh.fileno())
        os.chmod(tmp_path, 0o600)
        os.replace(tmp_path, os.path.join(_configured_dir, _STATE_NAME))
    except OSError as exc:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise ProviderUnavailable(
            "cannot write provider state: %s" % exc
        ) from exc
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise
    if phase == _PHASE_READY:
        # A switch/activation commits provider-state FIRST and only then the
        # new generation's health satellite as ready/0 (explicit commit: this
        # also supersedes a stale, lagging, ahead or corrupt health file,
        # unlike read-time convergence which must never rewrite one). A crash
        # in between simply rebuilds ready/0 at the next read because the old
        # health now lags the committed generation.
        _write_health(
            provider_id, generation, _HEALTH_STATUS_READY, 0
        )


# -- persisted active-provider failure threshold -----------------------------
# ``provider-health.json`` (0600) records the active provider's persistent
# failure threshold so the three-strike failover policy survives a restart and
# is shared across processes. It is written atomically (temp file, fsync,
# rename) as compact UTF-8 JSON with the fixed key order
# ``schema_version,provider_id,generation,status,consecutive_failures``, no
# ASCII escaping and no trailing newline: schema_version is the fixed integer
# 1, provider_id the non-empty id of the READY committed provider it belongs
# to, generation the positive committed generation it tracks, status one of
# ``ready``/``unavailable`` and consecutive_failures an integer 0..3. The file
# is a *satellite* of a ``ready`` ``provider-state.json``: it must carry the
# same (provider_id, generation). A missing file, or one lagging behind the
# committed generation, is rebuilt as ready/0. A corrupt file, one ahead of the
# committed generation, or one at the same generation with a different
# provider_id poisons provider calls (the fixed 503) and is never rewritten.
# A switch commits ``provider-state.json`` FIRST and only then the new
# generation's ready/0 health record, so a crash between them simply rebuilds
# ready/0 at the next read rather than ever trusting a stale failure count.
_HEALTH_NAME = "provider-health.json"
_HEALTH_SCHEMA_VERSION = 1
_HEALTH_STATUS_READY = "ready"
_HEALTH_STATUS_UNAVAILABLE = "unavailable"
_HEALTH_FAILURE_LIMIT = 3


class _HealthState(NamedTuple):
    """A parsed ``provider-health.json`` record."""

    provider_id: str
    generation: int
    status: str
    consecutive_failures: int


def _health_path() -> Optional[str]:
    if _configured_dir is None:
        return None
    return os.path.join(_configured_dir, _HEALTH_NAME)


def _parse_health(data) -> Optional[_HealthState]:
    """Validate a decoded health object; None when any field is invalid."""
    if not isinstance(data, dict):
        return None
    if set(data) != {
        "schema_version",
        "provider_id",
        "generation",
        "status",
        "consecutive_failures",
    }:
        return None
    version = data["schema_version"]
    provider_id = data["provider_id"]
    generation = data["generation"]
    status = data["status"]
    failures = data["consecutive_failures"]
    if not (
        type(version) is int
        and version == _HEALTH_SCHEMA_VERSION
        and isinstance(provider_id, str)
        and bool(provider_id)
        and type(generation) is int
        and generation >= 1
        and status in (_HEALTH_STATUS_READY, _HEALTH_STATUS_UNAVAILABLE)
        and type(failures) is int
        and 0 <= failures <= _HEALTH_FAILURE_LIMIT
    ):
        return None
    return _HealthState(
        provider_id=provider_id,
        generation=generation,
        status=status,
        consecutive_failures=failures,
    )


def _read_health() -> Optional[_HealthState]:
    """Return the persisted health record, or None if the file is absent.

    A missing/unreadable-as-absent file returns None. A present but corrupt or
    field-invalid file raises :class:`ProviderUnavailable` so the caller
    answers the fixed 503 and leaves the file byte-for-byte untouched.
    """
    path = _health_path()
    if path is None:
        return None
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise ProviderUnavailable(
            "cannot read provider health: %s" % exc
        ) from exc
    try:
        data = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise ProviderUnavailable("provider health file is corrupt") from exc
    health = _parse_health(data)
    if health is None:
        raise ProviderUnavailable("provider health file is corrupt")
    return health


def _write_health(
    provider_id: str,
    generation: int,
    status: str,
    consecutive_failures: int,
) -> None:
    """Atomically commit ``provider-health.json`` (0600, fsync + rename).

    Compact UTF-8 JSON, fixed key order
    ``schema_version,provider_id,generation,status,consecutive_failures``,
    non-ASCII written as-is, no trailing newline. The rename is the commit
    point. Raises :class:`ProviderUnavailable` on a write failure.
    """
    if _configured_dir is None:
        return
    payload = json.dumps(
        {
            "schema_version": _HEALTH_SCHEMA_VERSION,
            "provider_id": provider_id,
            "generation": generation,
            "status": status,
            "consecutive_failures": consecutive_failures,
        },
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode("utf-8")
    try:
        fd, tmp_path = tempfile.mkstemp(dir=_configured_dir, suffix=".tmp")
    except OSError as exc:
        raise ProviderUnavailable(
            "cannot write provider health: %s" % exc
        ) from exc
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(payload)
            fh.flush()
            os.fsync(fh.fileno())
        os.chmod(tmp_path, 0o600)
        os.replace(tmp_path, os.path.join(_configured_dir, _HEALTH_NAME))
    except OSError as exc:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise ProviderUnavailable(
            "cannot write provider health: %s" % exc
        ) from exc
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def _reconcile_health(state: _CommittedState) -> _HealthState:
    """Resolve the persisted health record against a READY committed state.

    ``state`` must be a ready committed record. Convergence rules:

    * the health file is absent, or belongs to an older generation (an
      id-bearing older generation counts as lagging): rebuild and persist it
      as ready/0 for the current committed id/generation;
    * the file is corrupt or field-invalid, is ahead of the committed
      generation, or sits at the same generation with a different
      provider_id: raise :class:`ProviderUnavailable` (the fixed 503) without
      rewriting anything.

    Returns the resolved health record for the current committed generation.
    """
    health = _read_health()
    if health is None or health.generation < state.generation:
        health = _HealthState(
            provider_id=state.provider_id,
            generation=state.generation,
            status=_HEALTH_STATUS_READY,
            consecutive_failures=0,
        )
        _write_health(
            health.provider_id,
            health.generation,
            health.status,
            health.consecutive_failures,
        )
        return health
    if health.generation > state.generation:
        raise ProviderUnavailable(
            "provider health record is ahead of the committed provider state"
        )
    if health.provider_id != state.provider_id:
        raise ProviderUnavailable(
            "provider health record does not match the committed provider id"
        )
    return health


class _FileLease:
    """A held shared/exclusive ``flock`` on a gate lock file.

    This is the cross-process half of the reconnect gate: provider calls
    hold a shared lease for their whole duration (in-flight calls in every
    process finish before a reconnect commits), while a reconnect commit or
    a first activation takes the exclusive lease. Acquisition polls with a
    non-blocking flock against the shared five-second deadline; a wait past
    it raises :class:`ProviderReconnectPending` with zero side effects. When
    no data directory is bound (or fcntl is unavailable) the lease is a
    no-op and the in-process gate alone applies.
    """

    def __init__(self, lock_name: str = _STATE_LOCK_NAME) -> None:
        self._lock_name = lock_name
        self._fd: Optional[int] = None

    def acquire(self, exclusive: bool, deadline: float) -> None:
        self.release()
        if _configured_dir is None or fcntl is None:
            return
        try:
            os.makedirs(_configured_dir, exist_ok=True)
            fd = os.open(
                os.path.join(_configured_dir, self._lock_name),
                os.O_RDWR | os.O_CREAT,
                0o600,
            )
        except OSError as exc:
            raise ProviderUnavailable(
                "cannot open provider state lock: %s" % exc
            ) from exc
        operation = fcntl.LOCK_EX if exclusive else fcntl.LOCK_SH
        try:
            while True:
                try:
                    fcntl.flock(fd, operation | fcntl.LOCK_NB)
                    break
                except InterruptedError:
                    continue
                except OSError as exc:
                    if exc.errno not in (
                        errno.EACCES,
                        errno.EAGAIN,
                        errno.EWOULDBLOCK,
                    ):
                        raise
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        raise ProviderReconnectPending(
                            "timed out waiting for the cross-process "
                            "provider gate"
                        )
                    time.sleep(min(0.05, remaining))
        except BaseException:
            os.close(fd)
            raise
        self._fd = fd

    def release(self) -> None:
        fd, self._fd = self._fd, None
        if fd is None:
            return
        try:
            fcntl.flock(fd, fcntl.LOCK_UN)
        except OSError:
            pass
        os.close(fd)


def _intent_probe_clear() -> bool:
    """Return whether no reconnect intent is currently held.

    The check is instantaneous and never BLOCKS on the lock and never retains
    the descriptor: an unheld exclusive lock always grants a shared trylock
    even while waiters are queued, so only a *held* reconnect intent reads as
    blocked. Ordinary calls use this to notice reconnect intent established
    after they began arriving; the descriptor (and its shared lock) is closed
    again immediately, so probing calls never queue behind -- and never
    leapfrog -- a reconnect waiting on the state lease.
    """
    if _configured_dir is None or fcntl is None:
        return True
    try:
        os.makedirs(_configured_dir, exist_ok=True)
        fd = os.open(
            os.path.join(_configured_dir, _INTENT_LOCK_NAME),
            os.O_RDWR | os.O_CREAT,
            0o600,
        )
    except OSError as exc:
        raise ProviderUnavailable(
            "cannot open provider reconnect lock: %s" % exc
        ) from exc
    try:
        while True:
            try:
                fcntl.flock(fd, fcntl.LOCK_SH | fcntl.LOCK_NB)
                return True
            except InterruptedError:
                continue
            except OSError as exc:
                if exc.errno in (errno.EACCES, errno.EAGAIN, errno.EWOULDBLOCK):
                    return False
                raise
    finally:
        try:
            fcntl.flock(fd, fcntl.LOCK_UN)
        except OSError:
            pass
        os.close(fd)


def _intent_wait_clear(budget: "_Budget") -> None:
    """Wait until no reconnect intent is held, bounded by ``budget``.

    Polls with the instant shared trylock rather than queueing a blocking
    shared flock: a waiting call must not hold a queue entry that an
    exclusive requester has to drain, otherwise a stream of waiting calls
    could starve reconnects (flock grants new shared locks ahead of a queued
    exclusive waiter on Linux).
    """
    while not _intent_probe_clear():
        if budget.expired():
            raise ProviderReconnectPending(
                "timed out waiting for provider reconnect to settle"
            )
        time.sleep(min(_POLL_SECONDS, budget.remaining()))


def _intent_lease() -> "_FileLease":
    """A lease on the reconnect-intent fence (caller acquires/releases)."""
    return _FileLease(_INTENT_LOCK_NAME)


@contextmanager
def _exclusive_state_lease(deadline: float):
    """Hold the exclusive cross-process state lease for one commit."""
    lease = _FileLease()
    lease.acquire(True, deadline)
    try:
        yield
    finally:
        lease.release()


def _healthy_within(provider, deadline) -> bool:
    """Bounded health probe; False (never raises) when unhealthy/too slow.

    ``deadline`` is either an absolute monotonic timestamp (the
    reconnect/switchover path, where one probe may use the whole remainder of
    that operation's five-second budget) or a :class:`_Budget` (the ordinary
    call path): with a budget the probe is capped at ONE second and may not
    pass the budget's non-resettable deadline either, and a result landing
    only after the wait is void (it reads as this one timeout and nothing
    else).
    """
    if isinstance(deadline, _Budget):
        timeout = min(HEALTH_PROBE_SECONDS, deadline.remaining())
    else:
        timeout = max(0.0, deadline - time.monotonic())
    return _health_with_limit(provider, timeout)


# Serializes per-process failure-counter updates; the matching cross-process
# serialization is the short exclusive flock on ``provider-health.lock`` taken
# in :func:`_health_counter_gate`. That fence is deliberately separate from the
# reconnect intent/drain gate: strikes one and two only bump a counter, so they
# must never drain in-flight calls or block on a switch. The actual single
# switch on a third strike still commits under the exclusive state lease inside
# :func:`_failover` (concurrent third strikes commit exactly once).
_health_lock = threading.Lock()
_HEALTH_LOCK_NAME = "provider-health.lock"


@contextmanager
def _health_counter_gate(budget: "_Budget"):
    """Hold the in-process lock AND a short exclusive cross-process counter
    flock around one failure-counter read-modify-write.

    Independent of the reconnect intent/drain gate, so ordinary failed probes
    never drain or block in-flight calls. The held shared provider-state lease
    of the calling :func:`provider_call` pins the committed generation for the
    duration; this fence only orders the counter writes of concurrent calls.
    """
    with _health_lock:
        lease = _FileLease(_HEALTH_LOCK_NAME)
        lease.acquire(True, budget.deadline)
        try:
            yield
        finally:
            lease.release()


def _reconcile_health_with_committed() -> Optional[_HealthState]:
    """Reconcile the health satellite with the ready committed state.

    Re-reads the committed ``provider-state.json`` (already reconciled and
    cached by this attempt's :func:`_sync_committed_state`) and resolves the
    health file for its current generation. Only a ready state has a health
    satellite; a ``switching`` state is completed/handled before this runs.
    Returns None when no data directory is bound (nothing to persist).
    """
    if _configured_dir is None:
        return None
    state = _read_committed_state()
    if state is None or state.phase != _PHASE_READY:
        # Should be unreachable on the admission path; refuse rather than
        # attach a failure count to a non-ready generation.
        raise ProviderUnavailable("provider state is not ready")
    return _reconcile_health(state)


class _ProbeDirective(NamedTuple):
    """What one ordinary call may do after its active-entry health probe.

    ``kind`` is ``"admit"``, ``"reject"`` or ``"switch"``. A switch directive
    carries the exact committed (provider_id, generation) that recorded the
    third strike, so the failover commits nothing when a concurrent third
    strike/reconnect already moved that generation (exactly one switch).
    """

    kind: str
    provider_id: str = ""
    generation: int = 0


def _active_probe_ready(budget: "_Budget", provider) -> "_ProbeDirective":
    """Probe the active instance and apply the persistent failure threshold.

    Runs on every ordinary provider call in chain mode, after the committed
    state and its health satellite are reconciled. Returns a directive:

    * ``admit``: the call may proceed on ``provider``;
    * ``reject``: the active entry is unhealthy but fewer than three
      consecutive failures are recorded -- the call is pinned to the fixed
      503 and NO switch happens;
    * ``switch``: the third consecutive failure -- the caller uses the
      budget remainder to fail over under the five-second intent/drain gate.

    A probe that returns the exact bool ``True`` clears the persisted count to
    ready/0 and admits. A ``False``, a non-bool, a raised probe, or one that
    does not return within its wait -- at most ONE second, and never past the
    attempt's non-resettable five-second budget; a late result is void -- is
    one failure: the persisted count is incremented (capped at three). On the
    third failure the active entry is re-verified once with the budget
    remainder (still capped at one second): recovery clears the count and
    admits, otherwise the caller performs the single failover, whose standby
    entries are then probed in chain order on the same remainder.
    """
    state = _read_committed_state()
    if state is None or state.phase != _PHASE_READY:
        raise ProviderUnavailable("provider state is not ready")
    if _healthy_within(provider, budget):
        _record_health(state, ready=True, budget=budget)
        return _ProbeDirective("admit")
    with _health_counter_gate(budget):
        # Re-read under the cross-process counter fence so two processes
        # failing the active entry concurrently cannot lose an increment.
        state = _read_committed_state()
        if state is None or state.phase != _PHASE_READY:
            raise ProviderUnavailable("provider state is not ready")
        health = _reconcile_health(state)
        failures = min(
            _HEALTH_FAILURE_LIMIT, health.consecutive_failures + 1
        )
        if failures < _HEALTH_FAILURE_LIMIT:
            # Strikes one and two: persist the failure and pin the call to
            # 503 without touching the active generation.
            _write_health(
                state.provider_id,
                state.generation,
                _HEALTH_STATUS_UNAVAILABLE,
                failures,
            )
            return _ProbeDirective("reject")
        # Third strike: re-verify the active entry once more inside the
        # failure gate, with the REMAINDER of the attempt's non-resettable
        # budget (still at most one second). A recovered active clears the
        # count and serves this very call; a still-unhealthy one records the
        # capped count and hands the remainder to the single failover.
        if _healthy_within(provider, budget):
            _write_health(
                state.provider_id,
                state.generation,
                _HEALTH_STATUS_READY,
                0,
            )
            return _ProbeDirective("admit")
        _write_health(
            state.provider_id,
            state.generation,
            _HEALTH_STATUS_UNAVAILABLE,
            _HEALTH_FAILURE_LIMIT,
        )
        return _ProbeDirective(
            "switch", state.provider_id, state.generation
        )


def _record_health(
    state: "_CommittedState", ready: bool, budget: Optional["_Budget"] = None
) -> None:
    """Persist a probe outcome, coalescing redundant ready/0 writes.

    The steady-state healthy path (the file already tracks this generation as
    ready/0) takes NO cross-process lock; the short counter flock is acquired
    only when a write may actually be needed, and the record is re-read under
    it so concurrent resets still converge.
    """
    if budget is None:
        budget = _Budget()
    if ready:
        peek = _read_health()
        if (
            peek is not None
